window.C5=window.C5||{};C5.math={"t":"গণিত","ch":[{"no":1,"title":"গুণ ও ভাগ","q":{"mcq":[{"n":"১(১)","q":"৭১৩ × ১☐; এক্ষেত্রে গুণফলের একক স্থানের অঙ্ক ৫ হলে, খালিঘরের অঙ্কটি কত হবে?","a":"গ) ৫","o":["৩","৪","৫","৬"]},{"n":"১(২)","q":"০, ১ ও ২ অঙ্কগুলো একবার ব্যবহার করে গঠিত বৃহত্তম ও ক্ষুদ্রতম সংখ্যার গুণফল কত?","a":"গ) ২১৪২০","o":["৬৩০","২৫২০","২১৪২০","২২৬২২"]},{"n":"১(৩)","q":"একটি বিদ্যালয়ে ১৩৫০ জন ছাত্র-ছাত্রী আছে। প্রত্যেক ছাত্র-ছাত্রী ২০০ টাকা করে দরিদ্র তহবিলে জমা দিলে কত টাকা হবে?","a":"খ) ২৭০০০০ টাকা","o":["২৭০০০ টাকা","২৭০০০০ টাকা","২৬০০০০ টাকা","২৭০০০০০ টাকা"]},{"n":"১(৪)","q":"৯৮৭৬৫ ÷ ১০০; এখানে ভাগশেষ কত হবে?","a":"ঘ) ৬৫","o":["৯৮","৯৮৭","৭৬৫","৬৫"]},{"n":"১(৫)","q":"ভাগের ক্ষেত্রে কোন সম্পর্কটি সত্য?","a":"খ) ভাগশেষ < ভাজক","o":["ভাজক < ভাগশেষ","ভাগশেষ < ভাজক","ভাজক ভাগশেষ","ভাজ্য < ভাগশেষ"]},{"n":"১(৬)","q":"২২৫ ÷ ☐ = ৯, ফাঁকা ঘরে কত বসবে?","a":"গ) ২৫","o":["৯","১৫","২৫","২২৫"]},{"n":"১(৭)","q":"তালেব সাহেব বছরে ৯৮৪০০ টাকা বাড়ি ভাড়ায় ব্যয় করেন। তার মাসিক বাড়ি ভাড়া ব্যয় কত?","a":"খ) ৮২০০ টাকা","o":["৮৪০০ টাকা","৮২০০ টাকা","৮০২০ টাকা","৮২০ টাকা"]}],"short":[{"n":"২(১)","q":"পাশাপাশি গুণ করি। ৫৯৬৮ × ৪৯৭","a":"৫৯৬৮ × (৪০০ + ৯০ + ৭)\n= (৫৯৬৮ × ৪০০) + (৫৯৬৮ × ৯০) + (৫৯৬৮ × ৭)\n= ২৩৮৭২০০ + ৫৩৭১২০ + ৪১৭৭৬\n= ২৯৬৬০৯৬"},{"n":"২(২)","q":"পাশাপাশি গুণ করি। ৯৫৪৭ × ৮৬৫","a":"৯৫৪৭ × ৮৬৫\n= ৯৫৪৭ × (৮০০ + ৬০ + ৫)\n= (৯৫৪৭ × ৮০০) + (৯৫৪৭ × ৬০) + (৯৫৪৭ × ৫)\n= ৭৬৩৭৬০০ + ৫৭২৮২০ + ৪৭৭৩৫\n= ৮২৫৮১৫৫"},{"n":"২(৩)","q":"পাশাপাশি গুণ করি। ৬৭৫৪ × ২৬৮৯","a":"৬৭৫৪ × ২৬৮৯\n= ৬৭৫৪ × (২০০০ + ৬০০ + ৮০ + ৯)\n= (৬৭৫৪ × ২০০০) + (৬৭৫৪ × ৬০০) + (৬৭৫৪ × ৮০) + (৬৭৫৪ × ৯)\n= ১৩৫০৮০০০ + ৪০৫২৪০০ + ৫৪০৩২০ + ৬০৭৮৬\n= ১৮১৬১৫০৬"},{"n":"২(৪)","q":"পাশাপাশি গুণ করি। ৯৮৭৯ × ৩৯৮৫","a":"৯৮৭৯ × ৩৯৮৫\n= ৯৮৭৯ × (৩০০০ + ৯০০ + ৮০ + ৫)\n= (৯৮৭৯ × ৩০০০) + (৯৮৭৯ × ৯০০) + (৯৮৭৯ × ৮০) + (৯৮৭৯ × ৫)\n= ২৯৬৩৭০০০ + ৮৮৯১১০০ + ৭৯০৩২০ + ৪৯৩৯৫\n= ৩৯৩৬৭৮১৫"},{"n":"২(৫)","q":"পাশাপাশি গুণ করি। ৭৯৯৮৭ × ৪২৭৪৯","a":"৭৯৯৮৭ × ৪২৭৪৯\n= ৭৯৯৮৭ × (৪০০০০ + ২০০০ + ৭০০ + ৪০ + ৯)\n= (৭৯৯৮৭ × ৪০০০০)+(৭৯৯৮৭ × ২০০০) + (৭৯৯৮৭ × ৭০০) + (৭৯৯৮৭ × ৪০) + (৭৯৯৮৭ ×\n৯)\n= ৩১৯৯৪৮০০০০ + ১৫৯৯৭৪০০০ + ৫৫৯৯০৯০০ + ৩১৯৯৪৮০ + ৭১৯৮৮৩\n= ৩৪১৯৩৬৪২৬৩"},{"n":"২(৬)","q":"পাশাপাশি গুণ করি। ২৬৫৮৮ × ৯৯৯৯","a":"২৬৫৮৮ × (১০০০০ – ১)\n= (২৬৫৮৮ × ১০০০০) – (২৬৫৮৮ × ১)\n= ২৬৫৮৮০০০০ – ২৬৫৮৮\n= ২৬৫৮৫৩৪১২"},{"n":"৫(১)","q":"সহজ পদ্ধতিতে গুণ করি। ১৯৯ × ২৫","a":"১৯৯ × ২৫\n= (২০০ – ১) × ২৫\n= (২০০ × ২৫) – (১ × ২৫)\n= ৫০০০ – ২৫\n= ৪৯৭৫"},{"n":"৫(২)","q":"সহজ পদ্ধতিতে গুণ করি। ৭২৪০ × ১১০","a":"= ৭২৪০ × (১০০ + ১০)\n= (৭২৪০ × ১০০) + (৭২৪০ × ১০)\n= ৭২৪০০০ + ৭২৪০০\n= ৭৯৬৪০০"},{"n":"৫(৩)","q":"সহজ পদ্ধতিতে গুণ করি। ৪৫২০ × ৯৯৮","a":"৪৫২০ × (১০০০ – ২)\n= (৪৫২০ × ১০০০) – (৪৫২০ × ২)\n= ৪৫২০০০০ – ৯০৪০\n= ৪৫১০৯৬০"},{"n":"৫(৪)","q":"সহজ পদ্ধতিতে গুণ করি। ৬৫২০ × ১০০১","a":"= ৬৫২০ × (১০০০ + ১)\n= (৬৫২০ × ১০০০) + (৬৫২০ × ১)\n= ৬৫২০০০০ + ৬৫২০\n= ৬৫২৬৫২০"},{"n":"৬(১)","q":"সহজ পদ্ধতিতে ভাগ করি। ৬৭৪৫৮ ÷ ১০০","a":"৬৭৪৫৮ ÷ ১০০\n= ৬৭৫.৫৮\n∴ ভাগফল = ৬৭৫\n∴ ভাগশেষ = ৫৮"},{"n":"৬(২)","q":"সহজ পদ্ধতিতে ভাগ করি। ৮২৫০০ ÷ ১০","a":"৮২৫০০ ÷ ১০\n= ৮২৫\n∴ ভাগফল = ৮২৫\n∴ ভাগশেষ = ০"},{"n":"৬(৩)","q":"সহজ পদ্ধতিতে ভাগ করি। ৯০৮৬৫ ÷ ১০০","a":"৯০৮৬৫ ÷ ১০০\n= ৯০৮.৬৫\n∴ ভাগফল = ৯০৮\n∴ ভাগশেষ = ৬৫"},{"n":"৬(৪)","q":"সহজ পদ্ধতিতে ভাগ করি। ৮৫২০০ ÷ ১০০","a":"৮৫২০০ ÷ ১০০\n= ৮৫২\n∴ ভাগফল = ৮৫২\n∴ ভাগশেষ = ০"},{"n":"৮","q":"কোনো বাড়িতে ৯৮০০০ গ্রাম চাল আছে। তাদের যদি প্রতিদিন ৬৫০ গ্রাম চাল লাগে, তবে কততম দিনে চাল শেষ হবে? (উত্তর ক্রমবাচক সংখ্যায়)","a":"৬৫০ গ্রাম চাল লাগে = ১ দিনে\n১ গ্রাম চাল লাগে = ১/৬৫০ দিনে\n∴ ৯৮০০০ গ্রাম চাল লাগে = ৯৮০০০/৬৫০ দিনে\nএখানে আমরা ভাগফল পাই, ১৫০ ও ভাগশেষ পাই ৫০। অর্থ্যাৎ, ১৫০দিন পর তাদের ৫০ গ্রাম চাল অবশিষ্ট থাকে। তাহলে, তাহলে চাল শেষ হবে ১৫১তম দিনে।"},{"n":"৯","q":"একটি বই তৈরি করতে ১৩৮ তা কাগজ লাগে। ৭০০০০ তা কাগজ দিয়ে কয়টি বই তৈরি করা যাবে?","a":"১৩৮ তা কাগজ দিয়ে তৈরি হয় ১টি বই\n১ তা কাগজ দিয়ে তৈরি হয় = ১/১৩৮ বই\n∴ ৭০০০০ তা কাগজ দিয়ে তৈরি হয় = ৭০০০০/১৩৮ টি বই\nএখানে, ভাগফল ৫০৭ এবং ভাগশেষ ৩৪। ৫০৭টি বই তৈরি করা যাবে এবং ৩৪তা কাগজ অবশিষ্ট থাকবে।"},{"n":"১০","q":"শফিক সাহেব তাঁর নিজ গ্রামের দরিদ্র মানুষের মাঝে ৭৫০টি ৫০০ টাকার নোট দান করলেন। তিনি মোট কত টাকা দান করলেন?","a":"১টি নোটের মান\n৫০০ টাকা\n∴ ৭৫০টি নোটের মান\n= (৭৫০ × ৫০০) টাকা\n= ৩৭৫০০০ টাকা"},{"n":"১১","q":"রাখি প্রতি মাসে ৯৫০ টাকা করে সঞ্চয় করে। কত তম মাসে তার সঞ্চিত টাকা ৫০০০০ অতিক্রম করবে? (উত্তর ক্রমবাচক সংখ্যায়)","a":"৯৫০ টাকা সঞ্চয় করে ১ মাসে\n১ টাকা সঞ্চয় করে = ১/৯৫০ মাসে\n∴ ৫০০০০ টাকা সঞ্চয় করে = ৫০০০০/৯৫০ মাসে\nএখানে, ভাগফল ৫২ এবং ভাগশেষ ৬০০ থাকে। ৫২মাস টাকা জমানোর পরও ৫০০০০টাকা হতে ৬০০ কম পড়ে। তাহলে, বলা যায় ৫৩তম মাসে ৫০০০০ টাকা অতিক্রম করবে।"},{"n":"১২","q":"আসাদ মুরগির খামার করার জন্য ৩৪৫টি ব্রয়লার মুরগি ২২৫ টাকা দরে ক্রয় করল। এতে তার কত টাকা খরচ হলো?","a":"১টি ব্রয়লার মুরগির দাম\n২২৫ টাকা\n৩৪৫টি ব্রয়লার মুরগির দাম = ২২৫ × ৩৪৫ টাকা। = ৭৭৬২৫ টাকা।\nউত্তর: ৭৭৬২৫ টাকা।"},{"n":"১৩","q":"একটি আলমারিতে ৫৬০টি বই রাখা যায়। এ রকম কতটি আলমারিতে ৩৭৯৬৮০টি বই রাখা যাবে?","a":"৫৬০টি বই রাখা যায় ১টি আলমারিতে\n১টি বই রাখা যায় = ১/৫৬০ টি আলমারিতে\n∴ ৩৭৯৬৮০টি বই রাখা যায় = ৩৭৯৬৮০/৫৬০ টি আলমারিতে\n= ৬৭৮ টি আলমারিতে\nউত্তর: ৬৭৮ টি আলমারিতে"},{"n":"১৪(ক)","q":"একজন পেঁয়াজ ব্যবসায়ী ১৮৮০ টাকা দরে ১২৬৪ বস্তা পেঁয়াজ ক্রয় করলেন। তিনি প্রতি বস্তা পেঁয়াজ ২১৫০ টাকা দরে বিক্রয় করলেন। পেঁয়াজ ক্রয় বাবদ তার কত টাকা খরচ হলো?","a":"১ বস্তা পেঁয়াজের ক্রয়মূল্য\n১৮৮০ টাকা\n∴ ১২৬৪ বস্তা পেঁয়াজের ক্রয়মূল্য\n= (১৮৮০ × ১২৬৪) টাকা\n= ২৩৭৬৩২০ টাকা"},{"n":"১৪(খ)","q":"একজন পেঁয়াজ ব্যবসায়ী ১৮৮০ টাকা দরে ১২৬৪ বস্তা পেঁয়াজ ক্রয় করলেন। তিনি প্রতি বস্তা পেঁয়াজ ২১৫০ টাকা দরে বিক্রয় করলেন। পেঁয়াজ বিক্রির পর তার কত টাকা লাভ হলো?","a":"প্রতি বস্তার বিক্রয়মূল্য\n২১৫০ টাকা\nপ্রতি বস্তার ক্রয়মূল্য\n১৮৮০ টাকা\n১ বস্তায় লাভ হয়\n= (২১৫০ – ১৮৮০) টাকা\n= ২৭০ টাকা\n১ বস্তায় লাভ হয়\n২৭০ টাকা\n∴ ১২৬৪ বস্তায় মোট লাভ হয়\n= (১২৬৪ × ২৭০) টাকা\n= ৩৪১২৮০ টাকা"}],"other":[{"n":"৩(১)","q":"ভাগ করি। ৫৪০০১ ÷ ৯০৭","a":"৫৯\n৯০৭) ৫৪০০১\n৪৫৩৫\n৮৬৫১\n৮১৬৩\n৪৮৮\n∴ ভাগফল = ৫৯\n∴ ভাগশেষ = ৪৮৮"},{"n":"৩(২)","q":"ভাগ করি। ২০৩৮৭ ÷ ৪০৬","a":"৫০\n৪০৬) ২০৩৮৭\n২০৩০\n৮৭\n০০\n৮৭\n∴ ভাগফল = ৫০\n∴ ভাগশেষ = ৮৭"},{"n":"৩(৩)","q":"ভাগ করি। ৯৩৩০০ ÷ ৬০০","a":"১৫৫\n৬০০) ৯৩৩০০\n৬০০\n৩৩৩০\n৩০০০\n৩৩০০\n৩০০০\n৩০০\n∴ ভাগফল = ১৫৫\n∴ ভাগশেষ = ৩০০"},{"n":"৩(৪)","q":"ভাগ করি। ৫৩৩৬২ ÷ ২৩০","a":"২৩২\n২৩০) ৫৩৩৬২\n৪৬০\n৭৩৬\n৬৯০\n৪৬২\n৪৬০\n২\n∴ ভাগফল = ২৩২\n∴ ভাগশেষ = ২"},{"n":"৩(৫)","q":"ভাগ করি। ৪৩৯৩২ ÷ ৫২৩","a":"৮৪\n৫২৩) ৪৩৯৩২\n৪১৮৪\n২০৯২\n২০৯২\n০\n∴ ভাগফল = ৮৪\n∴ ভাগশেষ = ০"},{"n":"৩(৬)","q":"ভাগ করি। ৮৪৮৬২ ÷ ৫৭৪","a":"১৪৭\n৫৭৪) ৮৪৮৬২\n৫৭৪\n২৭৪৬\n২২৯৬\n৪৫০২\n৪০১৮\n৪৮৪\n∴ ভাগফল = ১৪৭\n∴ ভাগশেষ = ৪৮৪"},{"n":"৪(১)","q":"উপরে-নিচে গুণ করি। ৮৮৬৭ × ৫৭৬","a":"৮৮৬৭\n× ৫৭৬\n৫৩২০২\n৬২০৬৯০\n৪৪৩৩৫০০\n৫১০৭৩৯২"},{"n":"৪(২)","q":"উপরে-নিচে গুণ করি। ৮৭৪৮ × ৪৬৯","a":"৮৭৪৮\n× ৪৬৯\n৭৮৭৩২\n৫২৪৮৮০\n৩৪৯৯২০০\n৪১০২৮১২"},{"n":"৪(৩)","q":"উপরে-নিচে গুণ করি। ৮৮৭০০ × ৯১০","a":"৮৮৭০০\n× ৯১০\n০০০০০\n৮৮৭০০০\n৭৯৮৩০০০০\n৮০৭১৭০০০"},{"n":"৪(৪)","q":"উপরে-নিচে গুণ করি। ৭৬৯০৩ × ৯০৪৮","a":"৭৬৯০৩\n× ৯০৪৮\n৬১৫২২৪\n৩০৭৬১২০\n০০০০০০০\n৬৯২১২৭০০০\n৬৯৫৮১৮৩৪৪"},{"n":"৪(৫)","q":"উপরে-নিচে গুণ করি। ৫৮৯৮৮ × ৭৬৬৩৯","a":"৫৮৯৮৮\n× ৭৬৬৩৯\n৫৩০৮৯২\n১৭৬৯৬৪০\n৩৫৩৯২৮০০\n৩৫৩৯২৮০০০\n৪১২৯১৬০০০০\n৪৫২০৭৮১৩৩২"},{"n":"৪(৬)","q":"উপরে-নিচে গুণ করি। ৬৮৭০ × ৫৮০০","a":"৬৮৭০\n× ৫৮০০\n০০০০\n০০০০০\n৫৪৯৬০০০\n৩৪৩৫০০০০\n৩৯৮৪৬০০০"}],"truefalse":[{"n":"৭(১)","q":"সঠিক কি না যাচাই করি। ২৯৮৪৫ ÷ ২৯৩-এর ভাগফল ১০১ ভাগশেষ ২৫২","a":"সত্য","e":"সঠিক।"},{"n":"৭(২)","q":"সঠিক কি না যাচাই করি। ৩৯৪৯৩ ÷ ৩২১-এর ভাগফল ১২৩ ভাগশেষ ১০","a":"সত্য","e":"সঠিক।"},{"n":"৭(৩)","q":"সঠিক কি না যাচাই করি। ৯৭৫০০ ÷ ১৮৬-এর ভাগফল ৫২৩ ভাগশেষ ২২২","a":"মিথ্যা","e":"ভুল।"}]}},{"no":2,"title":"গাণিতিক বাক্য","q":{"mcq":[{"n":"১(১)","q":"(১২ – ৭) × ২ – ২ = কত?","a":"খ) ৮","o":["১০","৮","৫","০"]},{"n":"১(২)","q":"কয়টি ৫০ টাকার নোট মিলে ২০০০ টাকা হয়?","a":"ঘ) ৪০টি","o":["২০০টি","১০০টি","৫০টি","৪০টি"]},{"n":"১(৩)","q":"জামিল ৩২ টাকা দিয়ে ৪টি কলম কিনল। ১৫টি কলম কেনার জন্য তার কত টাকা লাগবে?","a":"গ) ১২০ টাকা","o":["৫১ টাকা","৬০ টাকা","১২০ টাকা","১২৮ টাকা"]},{"n":"১(৪)","q":"১ ডজন পেনসিলের দাম ৪৮ টাকা হলে, ৮টি পেনসিলের দাম কত?","a":"ঘ) ৩২ টাকা","o":["৩৮৪ টাকা","৫৬ টাকা","৪০ টাকা","৩২ টাকা"]},{"n":"১(৫)","q":"৩৩৪টি আম ১৫ জনের মধ্যে সমানভাবে ভাগ করে দিলে কয়টি আম অবশিষ্ট থাকবে?","a":"ক) ৪টি","o":["৪টি","১৫টি","২২টি","৩৪টি"]},{"n":"১(৬)","q":"মাতার বয়স কন্যার বয়সের ৩ গুণ। কন্যার বয়স ১৫ বৎসর। ১০ বৎসর পর মাতার বয়স কত হবে?","a":"গ) ৫৫ বছর","o":["২৫ বছর","৪৫ বছর","৫৫ বছর","৭৫ বছর"]},{"n":"১(৭)","q":"৫ × ৬ ÷ ২ ☐ ৬ × ৬ – ৬ গাণিতিক বাক্যটির ফাঁকা ঘরে নিম্নের কোন প্রতীকটি বসবে?","a":"ক) <","o":["<",">","=","≤"]},{"n":"১(৮)","q":"খোলা বাক্যের উদাহরণ নিচের কোনটি?","a":"খ) ক × ৪ = ১৬","o":["৬ × ৪ = ২৪","ক × ৪ = ১৬","৮ ÷ ২ = ৪","৪ × ৪ = ১৬"]}],"short":[{"n":"২(১)","q":"ক সংখ্যক টেনিস বল এবং ৪টি ক্রিকেট ব্যাটের মূল্য একত্রে খ টাকা। ১টি টেনিস বলের মূল্য ২৬ টাকা এবং ১টি ক্রিকেট ব্যাটের মূল্য ১৮০ টাকা। ক এবং খ এর সম্পর্ক একটি গাণিতিক বাক্যে প্রকাশ করি।","a":"ক এবং খ এর সম্পর্ক দেখানো হলো: (ক × ২৬) + (৪ × ১৮০) = খ"},{"n":"২(২)","q":"ক সংখ্যক টেনিস বল এবং ৪টি ক্রিকেট ব্যাটের মূল্য একত্রে খ টাকা। ১টি টেনিস বলের মূল্য ২৬ টাকা এবং ১টি ক্রিকেট ব্যাটের মূল্য ১৮০ টাকা। খ এর মান নির্ণয় করি যখন ক = ৮","a":"(ক × ২৬) + (৪ × ১৮০) = খ\nবা, (৮ × ২৬) + (৪ × ১৮০) = খ\nবা, ২০৮ + ৭২০ = খ\nবা, ৯২৮ = খ\nবা, খ = ৯২৮"},{"n":"২(৩)","q":"ক সংখ্যক টেনিস বল এবং ৪টি ক্রিকেট ব্যাটের মূল্য একত্রে খ টাকা। ১টি টেনিস বলের মূল্য ২৬ টাকা এবং ১টি ক্রিকেট ব্যাটের মূল্য ১৮০ টাকা। ক এর মান নির্ণয় করি যখন খ = ১০৩২","a":"(ক × ২৬) + (৪ × ১৮০) = খ\nবা, ((ক × ২৬)) + ৭২০ = ১০৩২\nবা, ক × ২৬ = ১০৩২ – ৭২০\nবা, ক × ২৬ = ৩১২\nবা, ক = ১২"},{"n":"৩(১)","q":"হিসাব করি। ৭০ × [৬ + {২৪ – (৯ + ২ – ১)}]","a":"৭০ × [ ৬ + { ২৪ – ( ৯ + ২ – ১ ) } ]\n= ৭০ × [ ৬ + { ২৪ – ১০ } ]\n= ৭০ × [ ৬ + ১৪ ]\n= ৭০ × ২০\n= ১৪০০"},{"n":"৩(২)","q":"হিসাব করি। ১৮ ÷ [ ১ + ৪ ÷ { ১ + ৫ ÷ ( ১ + ৮ ÷ ২ ) } ]","a":"১৮ ÷ [ ১ + ৪ ÷ { ১ + ৫ ÷ ( ১ + ৮ ÷ ২ ) } ]\n= ১৮ ÷ [ ১ + ৪ ÷ { ১ + ৫ ÷ ( ১ + ৪ ) } ]\n= ১৮ ÷ [ ১ + ৪ ÷ { ১ + ৫ ÷ ৫ } ]\n= ১৮ ÷ [ ১ + ৪ ÷ { ১ + ১ } ]\n= ১৮ ÷ [ ১ + ৪ ÷ ২ ]\n= ১৮ ÷ [ ১ + ২ ]\n= ১৮ ÷ ৩\n=৬"},{"n":"৩(৩)","q":"হিসাব করি। ১১১ – [ ৮ ÷ { ২৩ – ( ১৬ + ৪ – ৫) } ]","a":"১১১ – [ ৮ ÷ { ২৩ – ( ১৬ + ৪ – ৫) } ]\n= ১১১ – [ ৮ ÷ { ২৩ – (২০ – ৫) } ]\n= ১১১ – [ ৮ ÷ { ২৩ – ১৫ } ]\n= ১১১ – [ ৮ ÷ ৮ ]\n= ১১১ – ১\n= ১১০"},{"n":"৪(১)","q":"নিচের গাণিতিক বাক্যগুলো দিয়ে গল্প তৈরি করি। (৩২ + ১৭) ÷ ৯","a":"রিমির কাছে ৩২টি লাল ও ১৭টি নীল মার্বেল ছিল। সে মোট মার্বেলগুলো ৯ জন বন্ধুকে সমানভাবে ভাগ করে\nদিলে প্রত্যেকে কয়টি করে পাবে?"},{"n":"৪(২)","q":"নিচের গাণিতিক বাক্যগুলো দিয়ে গল্প তৈরি করি। ৮০০ – (১২৫ × ৫ + ১৮ × ৬)","a":"প্রধান শিক্ষক বার্ষিক প্রতিযোগিতায় বিজয়ীদের উপহার দেওয়ার জন্য ৮০০ টাকা নিয়ে দোকানে গিয়ে ১২৫\nটাকা দামের ৫টি জ্যামিতি বক্স এবং সান্ত্বনা পুরস্কার হিসেবে আরও ৬ জনের জন্য ১৮ টাকা দামের ৬টি সুন্দর\nকলম কিনলেন। কেনাকাটা শেষে তার কাছে কত টাকা অবশিষ্ট রইল?"},{"n":"৫","q":"১২টি কলা এবং ৮টি পেঁপের মূল্য একত্রে ৬১৬ টাকা। একটি কলার মূল্য ৮ টাকা হলে একটি পেঁপের মূল্য কত?","a":"ধরি, ১টি পেঁপের মূল্য = ক টাকা\nতাহলে, গাণিতিক বাক্যটি হয়,\n(১২ × ৮) + (৮ × ক) = ৬১৬\nবা, ৯৬ + (৮ × ক) = ৬১৬\nবা, ৮ × ক = ৬১৬ – ৯৬\nবা, ৮ × ক = ৫২০\nবা, ক = ৫২০ ÷ ৮\nবা, ক = ৬৫\n∴ ১টি পেঁপের মূল্য ৬৫ টাকা।"},{"n":"৬","q":"৫টি গরু এবং ৮টি ছাগলের মূল্য একত্রে ৬২৫,৮০০ টাকা। একটি ছাগলের মূল্য ১৭৬০০ টাকা। একটি গরুর মূল্য কত?","a":"ধরি, ১টি গরুর মূল্য = ক টাকা\nতাহলে, গাণিতিক বাক্যটি হয়,\n(৫ × ক) + (৮ × ১৭৬০০) = ৬২৫৮০০\nবা, (৫ × ক) + ১৪০৮০০ = ৬২৫৮০০\nবা, ৫ × ক = ৬২৫৮০০ – ১৪০৮০০\nবা, ৫ × ক = ৪৮৫০০০\nবা, ক = ৪৮৫০০০ ÷ ৫\nবা, ক = ৯৭০০০\n∴ ১টি গরুর মূল্য ৯৭০০০ টাকা।"},{"n":"৭","q":"কেয়া এবং মারুফের মাসিক পারিবারিক খরচ একত্রে ৭০৫০০ টাকা। কেয়া অপেক্ষা মারুফের মাসিক খরচ ৫৬০০ টাকা বেশি। কেয়া ও মারুফ প্রত্যেকের মাসিক পারিবারিক খরচ কত?","a":"ধরি, কেয়ার মাসিক পারিবারিক খরচ = ক টাকা।\n∴ মারুফের মাসিক পারিবারিক খরচ = ক + ৫৬০০ টাকা।\nতাহলে, গাণিতিক বাক্যটি হয়,\nক + ক + ৫৬০০ = ৭০৫০০\nবা, ২ক + ৫৬০০ = ৭০৫০০\nবা, ২ক = ৭০৫০০ – ৫৬০০\nবা, ২ক = ৬৪৯০০\nবা, ক = ৬৪৯০০ ÷ ২\nবা, ক = ৩২৪৫০\n∴ কেয়ার মাসিক পারিবারিক খরচ = ৩২৪৫০ টাকা।\nও মারুফের মাসিক পারিবারিক খরচ = ৩২৪৫০ + ৫৬০০ = ৩৮০৫০ টাকা।"},{"n":"৮","q":"রনি এবং বাসিরের কাছে একত্রে ৭৮০টি লিচু আছে। রনি অপেক্ষা বাসিরের কাছে ৬৪টি লিচু কম আছে। রনি এবং বাসির প্রত্যেকের কতটি করে লিচু আছে?","a":"ধরি, রনির কাছে লিচু আছে = ক\n∴ বসিরের কাছে লিচু আছে = ক – ৬৪\nতাহলে, গাণিতিক বাক্যটি হয়,\nক + ক – ৬৪ = ৭৮০\nবা, ২ক – ৬৪ = ৭৮০\nবা, ২ক = ৭৮০ + ৬৪\nবা, ২ক = ৭৮০ + ৬৪\nবা, ২ক = ৮৪৪\nবা, ক = ৮৪৪ ÷ ২\nবা, ক = ৪২২\n∴ রনির কাছে লিচু আছে ৪২২ টি\nও বসিরের কাছে লিচু আছে ৪২২ – ৬৪ = ৩৫৮ টি"},{"n":"৯","q":"সাইফ সাহেব বাজার থেকে ২৫ কেজি চাল, ৩৫০ টাকার সরিষার তেল এবং ৬৬৮ টাকার মসলা কিনলেন। প্রতি কেজি চালের মূল্য ৭২ টাকা। তিনি দোকানদারকে ৩০০০ টাকা দিলেন। দোকানদার তাকে কত টাকা ফেরত দেবেন?","a":"উক্ত প্রশে্ন ক গাণিতিক বাক্যে রূপান্তর করলে আমরা পাই,\n৩০০০ – (২৫ × ৭২ + ৩৫০ + ৬৬৮)\n= ৩০০০ – (১৮০০ + ৩৫০ + ৬৬৮)\n= ৩০০০ – ২৮১৮\n= ১৮২\n∴ দোকানদার ১৮২টাকা ফেরত দেবে।"},{"n":"১০","q":"একটি ফলের দোকানে একটি আনারস ৪৮ টাকায়, একটি আনার ৯৫ টাকায় এবং একটি আতাফল ৭৫ টাকায় বিক্রি হয়। সোনিয়া ৪টি আনারস, ২টি আনার এবং ৫টি আতাফল কিনে ১০০০ টাকা দোকানিকে দিলে কত টাকা ফেরত পাবে?","a":"উক্ত প্রশে্ন ক গাণিতিক বাক্যে রূপান্তর করলে আমরা পাই,\n১০০০ – (৪৮ × ৪ + ২ × ৯৫ + ৫ × ৭৫)\n= ১০০০ – (১৯২ + ১৯০ + ৩৭৫)\n= ১০০০ – ৭৫৭\n= ২৪৩\n∴ দোকানদার ২৪৩ টাকা ফেরত দেবে।"},{"n":"১১","q":"ফাতিহা, সুলতান ও আফরিন তিন ভাইবোন তাদের বাবার সঙ্গে মেলায় গিয়ে নাগরদোলায় চড়ল। নাগরদোলায় প্রতিবার উঠলে ১৫ টাকা করে দিতে হয়। নাগরদোলায় ফাতিহা ৫বার, সুলতান ৭বার এবং আফরিন ১বার উঠলো। বাবা কাউন্টারে ৫০০ টাকা দিলেন। তিনি কত টাকা ফেরত পাবেন?","a":"উক্ত প্রশে্ন ক গাণিতিক বাক্যে রূপান্তর করলে আমরা পাই,\n৫০০ – {১৫ × (৫ + ৭ + ১)}\n= ৫০০ – {১৫ × (৫ + ৭ + ১)}\n= ৫০০ – {১৫ × ১৩}\n= ৫০০ – ১৯৫\n= ৩০৫\n∴ তিনি ৩০৫ টাকা ফেরত পাবেন।"},{"n":"১২","q":"মা এবং পুত্রের বয়সের সমষ্টি ৪৫ বছর। মায়ের বয়স পুত্রের বয়সের ৪ গুণ। তাদের প্রত্যেকের বয়স কত?","a":"ধরি, পুত্রের বয়স = ক বছর\n∴ মায়ের বয়স = ক × ৪ = ৪ক বছর\nতাহলে, গাণিতিক বাক্যটি হয়,\nক + ৪ক = ৪৫\nবা, ৫ক = ৪৫\nবা, ক = ৪৫ ÷ ৫\nবা, ক = ৯\n∴ পুত্রের বয়স ৯ বছর ও মায়ের বয়স ৪ক = ৪ × ৯ = ৩৬ বছর।"},{"n":"১৩","q":"একজন শ্রমিক ৫ দিনে ৩১২৫ টাকা আয় করেন। ৩ সপ্তাহে তিনি কত টাকা আয় করেন?","a":"আমরা জানি, ১ সপ্তাহ = ৭ দিন\n৩ সপ্তাহ = ৩ × ৭ = ২১ দিন\n৫ দিনে আয় হয় ৩১২৫ টাকা\n১ দিনে আয় হয় ৩২১৫ ÷ ৫ = ৬২৩ টাকা\n২১ দিনে আয় হয় ৬২৫ × ২১ = ১৩১২৫ টাকা\n্উত্তর: ১৩১২৫ টাকা।"},{"n":"১৪","q":"শরিফুল ৭২ টাকা দিয়ে ৩টি খাতা কিনল। ১২টি খাতা কিনতে তার কত টাকা লাগবে?","a":"৩টি খাতার দাম ৭২ টাকা\n১টি খাতার দাম ৭২ ÷ ৩ = ২৪ টাকা\n১২টি খাতার দাম ২৪ × ১২ = ২৮৮ টাকা\nউত্তর: ২৮৮ টাকা।"},{"n":"১৫(ক)","q":"১৬ জন শ্রমিক ৭ দিনে একটি দেয়াল নির্মাণ করে। ৪ জন শ্রমিকের ঐ দেয়ালটি নির্মাণ করতে কতদিন লাগবে?","a":"১৬ জন শ্রমিকের সময় লাগে ৭ দিন\n১ জন শ্রমিকের সময় লাগে ৭ × ১৬ = ১১২ দিন\n৪ জন শ্রমিকের সময় লাগে ১১২ ÷ ৪ = ২৮ দিন\nউত্তর: ২৮ দিন।"},{"n":"১৫(খ)","q":"১৬ জন শ্রমিক ৭ দিনে একটি দেয়াল নির্মাণ করে। দেয়ালটি ২ দিনে নির্মাণ করতে অতিরিক্ত কতজন শ্রমিক লাগবে?","a":"৭ দিনে নির্মাণ করতে শ্রমিক লাগে\n১৬ জন\n১ দিনে নির্মাণ করতে লাগে\n= (১৬ × ৭) = ১১২ জন শ্রমিক\n২ দিনে নির্মাণ করতে লাগে\n= (১১২ ÷ ২) = ৫৬ জন শ্রমিক\nআগে থেকেই শ্রমিক ছিল ১৬ জন।\n∴ অতিরিক্ত শ্রমিক লাগবে (৫৬ – ১৬) = ৪০ জন।"}]}},{"no":3,"title":"গুণিতক ও গুণনীয়ক","q":{"mcq":[{"n":"১(১)","q":"নিম্নের কোন দুইটি সংখ্যার ন্যূনতম সাধারণ গুণিতক ৩০?","a":"গ) ৫ ও ৬","o":["৩ ও ৫","৩ ও ৬","৫ ও ৬","৫ ও ১০"]},{"n":"১(২)","q":"৩টি বাস যথাক্রমে ৩, ৪ ও ৫ মিনিট পর পর থামে। ন্যূনতম কতক্ষণ পর বাস ৩টি একত্রে থামবে?","a":"ঘ) ৬০ মিনিট","o":["১২ মিনিট","১৫ মিনিট","২০ মিনিট","৬০ মিনিট"]},{"n":"১(৩)","q":"৫ ও ৭ এর গসাগু কত?","a":"ঘ) ১","o":["৩৫","১২","২","১"]},{"n":"১(৪)","q":"১৫টি আম ও ২৫টি লিচু সর্বাধিক কতজন শিক্ষার্থীর মধ্যে সমানভাবে ভাগ করে দেওয়া যাবে?","a":"ঘ) ৫","o":["২৫","১৫","১০","৫"]}],"short":[{"n":"২","q":"লসাগু ও গসাগু এর পূর্ণরূপ লিখি।","a":"লসাগু : লঘিষ্ঠ সাধারণ গুণিতক।\nগসাগু : গরিষ্ঠ সাধারণ গুণনীয়ক।"},{"n":"৩(১)","q":"নিচের সংখ্যাগুলো ৩ দ্বারা বিভাজ্য কি না যাচাই করি। ৪২৩","a":"৪২৩ সংখ্যাটির অঙ্কগুলোর যোগফল = ৪ + ৩ + ২ = ৯\n৯ সংখ্যাটি ৩ দ্বারা বিভাজ্য।\n∴ ৪২৩ সংখ্যাটি ৩ দ্বারা বিভাজ্য।"},{"n":"৩(২)","q":"নিচের সংখ্যাগুলো ৩ দ্বারা বিভাজ্য কি না যাচাই করি। ৬৪৩","a":"৬৪৩ সংখ্যাটির অঙ্কগুলোর যোগফল = ৬ + ৪ + ৩ = ১৩\n১৩ সংখ্যাটি ৩ দ্বারা বিভাজ্য নয়।\n∴ ৬৪৩ সংখ্যাটি ৩ দ্বারা বিভাজ্য নয়।"},{"n":"৩(৩)","q":"নিচের সংখ্যাগুলো ৩ দ্বারা বিভাজ্য কি না যাচাই করি। ৯৩১","a":"৯৩১ সংখ্যাটির অঙ্কগুলোর যোগফল = ৯ + ৩ + ১ = ১৩\n১৩ সংখ্যাটি ৩ দ্বারা বিভাজ্য নয়।\n∴ ৯৩১ সংখ্যাটি ৩ দ্বারা বিভাজ্য নয়।"},{"n":"৩(৪)","q":"নিচের সংখ্যাগুলো ৩ দ্বারা বিভাজ্য কি না যাচাই করি। ৯০৩১২","a":"৯৩১ সংখ্যাটির অঙ্কগুলোর যোগফল = ৯ + ০ + ৩ + ১ + ২ = ১৫\n১৫ সংখ্যাটি ৩ দ্বারা বিভাজ্য।\n∴ ৯০৩১২ সংখ্যাটি ৩ দ্বারা বিভাজ্য।"},{"n":"৪(১)","q":"নিচের সংখ্যাগুলো ৪ দ্বারা বিভাজ্য কি না যাচাই করি। ৭৩২","a":"একক ও দশক স্থানের সংখ্যাটি হচ্ছে ৩২। যা ৪ দ্বারা বিভাজ্য।\n∴ ৭৩২ সংখ্যাটি ৪ দ্বারা বিভাজ্য।"},{"n":"৪(২)","q":"নিচের সংখ্যাগুলো ৪ দ্বারা বিভাজ্য কি না যাচাই করি। ৯০৮","a":"একক ও দশক স্থানের সংখ্যাটি হচ্ছে ০৮। যা ৪ দ্বারা বিভাজ্য।\n∴ ৯০৮ সংখ্যাটি ৪ দ্বারা বিভাজ্য।"},{"n":"৪(৩)","q":"নিচের সংখ্যাগুলো ৪ দ্বারা বিভাজ্য কি না যাচাই করি। ১০২৮","a":"একক ও দশক স্থানের সংখ্যাটি হচ্ছে ২৮। যা ৪ দ্বারা বিভাজ্য।\n∴ ১০২৮ সংখ্যাটি ৪ দ্বারা বিভাজ্য।"},{"n":"৪(৪)","q":"নিচের সংখ্যাগুলো ৪ দ্বারা বিভাজ্য কি না যাচাই করি। ৯২৫০০","a":"একক ও দশক স্থানের সংখ্যাটি হচ্ছে ০০। একক ও দশক স্থানে ০০ থাকলে সংখ্যাটি ৪ দ্বারা বিভাজ্য।\n∴ ৯২৫০০ সংখ্যাটি ৪ দ্বারা বিভাজ্য।"},{"n":"৫","q":"৭ ও ১৩ এর লসাগু কত?","a":"৭ এবং ১৩ উভয়ই মৌলিক সংখ্যা।\nআমরা জানি, যদি সংখ্যাগুলোর মধ্যে ১ ছাড়া অন্য কোনো সাধারণ গুণনীয়ক না থাকে, তবে তাদের গুণফলই\nহয় লসাগু।\n∴ লসাগু = ৭ × ১৩ = ৯১"},{"n":"৬","q":"১৩ ও ১৭ এর গসাগু কত?","a":"১৩ এবং ১৭ উভয়ই মৌলিক সংখ্যা।\nমৌলিক সংখ্যাগুলোর মধ্যে ১ ছাড়া অন্য কোনো সাধারণ গুণনীয়ক থাকে না। তাই এদের গরিষ্ঠ সাধারণ\nগুণনীয়ক বা গসাগু সবসময় ১ হয়।\n∴ ১৩ ও ১৭ গসাগু হচ্ছে ১।"},{"n":"৭(১)","q":"লসাগু নির্ণয় করি। ৯, ১৫","a":"৩ ৯, ১৫\n৩, ৫\n∴ ৯ ও ১৫ এর লসাগু = ৩ × ৩ × ৫ = ৪৫"},{"n":"৭(২)","q":"লসাগু নির্ণয় করি। ২৪, ২৭","a":"৩ ২৪, ২৭\n৮, ৯\n∴ ২৪ ও ২৭ এর লসাগু = ৩ × ৮ × ৯ = ২১৬"},{"n":"৭(৩)","q":"লসাগু নির্ণয় করি। ৭, ১৫","a":"১ ৭, ১৫\n৭, ১৫\n∴ ৭ ও ১৫ এর লসাগু = ৭ × ১৫ = ১০৫"},{"n":"৭(৪)","q":"লসাগু নির্ণয় করি। ৬, ৯, ১২","a":"৩ ৬, ৯, ১২\n২ ২, ৩, ৪\n১, ৩, ২\n∴ ৬, ৯ ও ১২ এর লসাগু = ৩ × ২ × ৩ × ২ = ৩৬"},{"n":"৭(৫)","q":"লসাগু নির্ণয় করি। ৮, ১২, ১৬","a":"২ ৮, ১২, ১৬\n২ ৪, ৬, ৮\n২ ২, ৩, ৪\n১, ৩, ২\n∴ ৮, ১২ ও ১৬ এর লসাগু = ২ × ২ × ২ × ৩ × ২ = ৪৮"},{"n":"৭(৬)","q":"লসাগু নির্ণয় করি। ৭, ১০, ১২, ১৪","a":"২ ৭, ১০, ১২, ১৪\n৭ ৭, ৫, ৬, ৭\n১, ৫, ৬, ১\n∴ ৭, ১০, ১২ ও ১৪ এর লসাগু = ২ × ৭ × ৫ × ৬ = ৪২০"},{"n":"৭(৭)","q":"লসাগু নির্ণয় করি। ৬, ৮, ১২, ১৬","a":"২ ৬, ৮, ১২, ১৬\n২ ৩, ৪, ৬, ৮\n২ ৩, ২, ৩, ৪\n৩ ৩, ১, ৩, ২\n১, ১, ১, ২\n∴ ৬, ৮, ১২ ও ১৬ এর লসাগু = ২ × ২ × ২ × ৩ × ২ = ৪৮"},{"n":"৭(৮)","q":"লসাগু নির্ণয় করি। ৯, ১২, ১৫, ১৮","a":"৩ ৯, ১২, ১৫, ১৮\n৩ ৩, ৪, ৫, ৬\n২ ১, ৪, ৫, ২\n১, ২, ৫, ১\n∴ ৬, ৮, ১২ ও ১৬ এর লসাগু = ৩ × ৩ × ২ × ২ × ৫ × ১ = ১৮০"},{"n":"৮(১)","q":"গসাগু নির্ণয় করি। ৯, ১৫","a":"৩ ৯, ১৫\n৩, ৫\n∴ ৯ ও ১৫ এর গসাগু = ৩"},{"n":"৮(২)","q":"গসাগু নির্ণয় করি। ২১, ৩০","a":"৩ ২১, ৩০\n৭, ১০\n∴ ২১ ও ৩০ এর গসাগু = ৩"},{"n":"৮(৩)","q":"গসাগু নির্ণয় করি। ৩২, ৩৬","a":"২ ৩২, ৩৬\n২ ১৬, ১৮\n৮, ৯\n∴ ৩২ ও ৩৬ এর গসাগু = ২ × ২ = ৪"},{"n":"৮(৪)","q":"গসাগু নির্ণয় করি। ১৩, ১৪","a":"১ ১৩, ১৪\n১৩, ১৪\n∴ ১৩ ও ১৪ এর গসাগু = ১"},{"n":"৮(৫)","q":"গসাগু নির্ণয় করি। ১২, ১৮, ২৪","a":"২ ১২, ১৮, ২৪\n৩ ৬, ৯, ১২\n২, ৩, ৪\n∴ ১২, ১৮ ও ২৪ এর গসাগু = ২ × ৩ = ৬"},{"n":"৮(৬)","q":"গসাগু নির্ণয় করি। ১২, ২৪, ৩৬","a":"২ ১২, ২৪, ৩৬\n২ ৬, ১২, ১৮\n৩ ৩, ৬, ৯\n১, ২, ৩\n∴ ১২, ২৪ ও ৩৬ এর গসাগু = ২ × ২ × ৩ = ১২"},{"n":"৮(৭)","q":"গসাগু নির্ণয় করি। ২৬, ৩৯, ৫২","a":"১৩ ২৬, ৩৯, ৫২\n২, ৩, ৪\n∴ ২৬, ৩৯ ও ৫২ এর গসাগু = ১৩"},{"n":"৮(৮)","q":"গসাগু নির্ণয় করি। ৮, ১২, ১৬, ৩৬","a":"২ ৮, ১২, ১৬, ৩৬\n২ ৪, ৬, ৮, ১৮\n২, ৩, ৪, ৯\n∴ ৮, ১২, ১৬ ও ৩৬ এর গসাগু = ২ × ২ = ৪"},{"n":"৯","q":"সবচেয়ে ছোটো কোন সংখ্যা ৯ ও ১২ দ্বারা বিভাজ্য?","a":"সবচেয়ে ছোট যে সংখ্যাটি ৯ ও ১২ দ্বারা বিভাজ্য, তা হলো এই সংখ্যা দুটির লঘিষ্ঠ সাধারণ গুণিতক বা লসাগু।\n৩ ৯, ১২\n৩, ৪\n∴ ৯ ও ১২ এর গসাগু = ৩ × ৩ × ৪ = ৩৬\nউত্তর: সবচেয়ে ছোটো ৩৬ সংখ্যা ৯ ও ১২ দ্বারা বিভাজ্য।"},{"n":"১০","q":"পঞ্চম শ্রেণির ১৮ জন ছেলে ও ২৭ জন মেয়ের মধ্যে সমানভাবে ভাগ করে দেওয়ার জন্য সর্বনিম্ন কতটি চকলেট লাগবে?","a":"৮ জন ছেলে ও ২৭ জন মেয়ের জন্য চকলেটের সংখ্যা ১৮ ও ২৭ এর লসাগু হবে।\n৩ ১৮, ২৭\n৩ ৬, ৯\n২, ৩\n∴ ১৮ ও ২৮ এর গসাগু = ৩ × ৩ × ২ × ৩ = ৫৪\nউত্তর: সর্বনিম্ন ৫৪টি চকলেট লাগবে।"},{"n":"১১","q":"সর্বাধিক কতজন শিক্ষার্থীর মধ্যে ২২টি আম ও ৬৬টি লিচু সমানভাবে ভাগ করে দেওয়া যাবে?","a":"২২টি আম ও ৬৬টি লিচু সর্বাধিক শিক্ষার্থীদের মধ্যে সমানভাবে বিতরনের জন্য আমাদের ২২ ও ৬৬ এর গসাগু\nকরতে হবে।\n২ ২২, ৬৬\n১১ ১১, ৩৩\n১, ৩\n∴ ২২ ও ৬৬ এর গসাগু = ২ × ১১ = ২২\nউত্তর: সর্বাধিক ২২ জন শিক্ষার্থীর মধ্যে আম ও লিচু সমানভাবে দেওয়া যাবে।"},{"n":"১২","q":"একটি রাস্তায় ১২ মিটার পরপর গাছ ও ২০ মিটার পরপর ল্যাম্পপোস্ট আছে। রাস্তার শুরুতে গাছ এবং ল্যাম্পপোস্ট পাশাপাশি থাকলে কত মিটার পরপর গাছ এবং ল্যাম্পপোস্ট পুনরায় পাশাপাশি থাকবে?","a":"এই সমস্যাটি সমাধানের জন্য আমাদের ১২ ও ২০-এর লসাগু বের করতে হবে।\n২ ১২, ২০\n২ ৬, ১০\n৩, ৫\n∴ ১২ ও ২০ এর লসাগু = ২ × ২ × ৩ × ৫ = ৬০\nউত্তর: প্রতি ৬০ মিটার পরপর গাছ এবং ল্যাম্পপোস্ট পুনরায় পাশাপাশি থাকবে।"},{"n":"১৩(১)","q":"তিনটি ঘণ্টা একত্রে বাজার পর যথাক্রমে ১৫, ২০, ২৫ মিনিট অন্তর বাজতে লাগল। কতক্ষণ পর ঘণ্টাগুলো আবার একসঙ্গে বাজবে?","a":"১৫, ২০ ও ২৫ এর লসাগু হবে উক্ত ঘন্টাগুলো একাসাথে বেজে উঠার সময়।\n৫ ১৫, ২০, ২৫\n৩, ৪, ৫\n∴ ১৫, ২০ ও ২৫ এর লসাগু = ৫ × ৩ × ৪ × ৫ = ৩০০\nঅর্থাৎ, ঘণ্টাগুলো ৩০০ মিনিট পর আবার একসঙ্গে বাজবে।\nআমরা জানি,\n৬০ মিনিট = ১ ঘণ্টা\n৩০০ মিনিট = ৩০০ ÷ ৬০ = ৫ ঘণ্টা।\nউত্তর: ঘণ্টাগুলো ৫ ঘণ্টা পর আবার একসঙ্গে বাজবে।"},{"n":"১৩(২)","q":"তিনটি ঘণ্টা একত্রে বাজার পর যথাক্রমে ১৫, ২০, ২৫ মিনিট অন্তর বাজতে লাগল। ঘণ্টা তিনটি দুপুর ১টায় বাজার পর পরবর্তীকালে কোন সময় পুনরায় একত্রে বাজবে?","a":"ঘণ্টাগুলো সর্বশেষ একত্রে বেজেছিল দুপুর ১টায়।\n∴ পরবর্তী সময় হবে = (দুপুর ১টা + ৫ ঘণ্টা) = সন্ধ্যা ৬টা।\nউত্তর: ঘণ্টাগুলো পরবর্তীকালে সন্ধ্যা ৬টায় পুনরায় একত্রে বাজবে।"},{"n":"১৪(১)","q":"নিচে একটি আয়তাকার মেঝের ছবি দেওয়া আছে। কোনো খালি জায়গা না রেখে আমরা মেঝেতে বর্গাকার কার্পেট বসাতে চাই। মেঝেতে বসানো যাবে এমন বৃহত্তম কার্পেটের এক বাহুর দৈর্ঘ্য নির্ণয় করো।","a":"মেঝের দৈর্ঘ্য ও প্রস্থ বরাবর কোনো খালি জায়গা না রেখে সবচেয়ে বড় মাপের বর্গাকার কার্পেট বসাতে হলে\nআমাদের ৪৮ ও ৩৬-এর গসাগু বের করতে হবে।\n২ ৪৮, ৩৬\n২ ২৪, ১৮\n৩ ১২, ৯\n৪, ৩\n∴ ৪৮ ও ৩৬ এর গসাগু = ২ × ২ × ৩ = ১২\nউত্তর: মেঝেতে বসানো যাবে এমন বৃহত্তম কার্পেটের এক বাহুর দৈর্ঘ্য ১২ মিটার।"},{"n":"১৪(২)","q":"নিচে একটি আয়তাকার মেঝের ছবি দেওয়া আছে। কোনো খালি জায়গা না রেখে আমরা মেঝেতে বর্গাকার কার্পেট বসাতে চাই। সম্পূর্ণ মেঝেতে কার্পেট বিছানোর জন্য এরূপ কয়টি কার্পেট লাগবে?","a":"দৈর্ঘ্য বরাবর ১টি কলামে কার্পেট লাগবে = ৪৮ ÷ ১২ = ৪টি\nপ্রস্থ বরাবর ১টি কলামে কার্পেট লাগবে = ৩৬ ÷ ১২ = ৩টি।\n∴ মোট কার্পেট লাগবে = ৪ × ৩ = ১২টি।"},{"n":"১৫(১)","q":"একটি ঝুড়িতে ৪২টি আম ও ১০৫টি লিচু আছে। সর্বাধিক কতজন শিক্ষার্থীর মধ্যে আম ও লিচু সমানভাবে ভাগ করে দেয়া যাবে?","a":"সর্বাধিক কতজন শিক্ষার্থীর মধ্যে আম ও লিচু সমানভাবে দেওয়া যাবে তার জন্য আমাদের ৪২ ও ১০৫ এর\nগসাগু বের করতে হবে।\n৩ ৪২, ১০৫\n৭ ১৪, ৩৫\n২, ৫\n∴ ৪২ ও ১০৫ এর গসাগু = ৩ × ৭ = ২১\nউত্তর: সর্বাধিক ২১ জন শিক্ষার্থীর মধ্যে আম ও লিচু সমানভাবে ভাগ করে দেওয়া যাবে।"},{"n":"১৫(২)","q":"একটি ঝুড়িতে ৪২টি আম ও ১০৫টি লিচু আছে। প্রত্যেকে কয়টি করে আম ও লিচু পাবে?","a":"শিক্ষার্থীর সংখ্যা ২১ জন। এখন আম ও লিচুর সংখ্যাকে এই ২১ দিয়ে ভাগ করলে প্রত্যেকের প্রাপ্ত ফলের সংখ্যা\nপাওয়া যাবে।\nপ্রত্যেকে আম পাবে: ৪২ ÷ ২১ = ২টি\nপ্রত্যেকে লিচু পাবে: ১০৫ ÷ ২১ = ৫টি।\nউত্তর: প্রত্যেকে ২টি করে আম এবং ৫টি করে লিচু পাবে।"}]}},{"no":4,"title":"সাধারণ ভগ্নাংশ","q":{"mcq":[{"n":"১(১)","q":"১৭/৫ এর মিশ্র ভগ্নাংশ কোনটি?","a":"গ) ৩ ২/৫","o":["১ ৭/৫","২ ২/৫","৩ ২/৫","২ ৩/৫"]},{"n":"১(২)","q":"নিচের কোনটি সবচেয়ে বড়ো?","a":"ক) ৩/৪","o":["৩/৪","৩/৫","৩/৭","৩/৮"]},{"n":"১(৩)","q":"২৮/৫৬ এর লঘিষ্ঠ আকার নিচের কোনটি?","a":"ঘ) ১/২","o":["১৪/২৮","৭/১৪","৪/৮[?]","১/২"]}],"short":[{"n":"২(১)","q":"হিসাব করি। ২/৯ + ১২/৫","a":"২/৯ + ১২/৫\n= ১০/৪৫ + ১০৮/৪৫\n= (১০ + ১০৮)/৪৫\n= ১১৮/৪৫"},{"n":"২(২)","q":"হিসাব করি। ৩ ১/৩ + ২ ৪/৯","a":"৩ ১/৩ + ২ ৪/৯\n= ১০/৩ + ২২/৯\n= ৩০/৯ + ২২/৯\n= (৩০ + ২২)/৯\n= ৫২/৯"},{"n":"২(৩)","q":"হিসাব করি। ২/৯ – ১২/৫","a":"২/৯ – ১২/৫\n= ১০/৪৫ – ১০৮/৪৫\n= (১০ – ১০৮)/৪৫\n= –৯৮/৪৫\n= –৯৮/৪৫"},{"n":"২(৪)","q":"হিসাব করি। ৩ ১/৬ – ২ ১/১০","a":"৩ ১/৬ – ২ ১/১০\n= ১৯/৬ – ২১/১০\n= ৯৫/৩০ – ৬৩/৩০\n= (৯৫ – ৬৩)/৩০\n= ৩২/৩০\n= ১৬/১৫"},{"n":"২(৫)","q":"হিসাব করি। ৩/৪ + ৭/৮ – ১১/১২","a":"৩/৪ + ৭/৮ – ১১/১২\n= ১৮/২৪ + ২১/২৪ – ২২/২৪\n= (১৮ + ২১ – ২২)/২৪\n= ১৭/২৪"},{"n":"২(৬)","q":"হিসাব করি। ১ ১/৩ + ৩ ১/৪ – ২ ৫/৬ – ৩/৪","a":"১ ১/৩ + ৩ ১/৪ – ২ ৫/৬ – ৩/৪\n= ৪/৩ + ১৩/৪ – ১৭/৬ – ৩/৪\n= ১৬/১২ + ৩৯/১২ – ৩৪/১২ – ৯/১২\n= (১৬ + ৩৯ – ৩৪ – ৯)/১২\n= ১২/১২\n= ১"},{"n":"৩","q":"৩ ৩/৪ মিটার ও ২ ১/৩ মিটার দৈর্ঘ্যের দুইটি ফিতা একত্রে কত মিটার?","a":"১ম ফিতা ৩ ৩/৪ = ১৫/৪\n২য় ফিতা ২ ১/৩ = ৭/৩\nমোট দৈর্ঘ্য = ১৫/৪ + ৭/৩\n= ৪৫/১২ + ২৮/১২\n= (৪৫ + ২৮)/১২\n= ৭৩/১২\nউত্তর: ৭৩/১২ মিটার।"},{"n":"৪","q":"গীতার কাছে ১ ৫/৬ লিটার ও মামুনের কাছে ১৩/৮ লিটার জুস আছে। কার জুসের পরিমাণ বেশি এবং কত বেশি?","a":"গীতার কাছে আছে ১ ৫/৬ = ১১/৬ = ৪৪/২৪\nমামুনের কাছে আছে ১৩/৮ = ৩৯/২৪\nদুটো ভগ্নাংশের মধ্যে ৪৪/২৪ ভগ্নাংশের লব বড়।\n∴ গীতার জুসের পরিমান বেশি।\nগীতার জুসের পরিমান বেশি = ৪৪/২৪ – ৩৯/২৪\n= (৪৪ – ৩৯)/২৪\n= ৫/২৪\nউত্তর: ৫/২৪ অংশ বেশি।"},{"n":"৫(ক)","q":"সবুজের বাড়ি বিদ্যালয় থেকে ৩/৮ কিমি পশ্চিমে অবস্থিত। মিতুর বাড়ি বিদ্যালয় থেকে ৫/১২ কি মি পূর্বে অবস্থিত। সবুজের বাড়ি থেকে মিতুর বাড়ির দূরত্ব কত কিমি?","a":"সবুজের বাড়ি থেকে বিদ্যালয়ের দুরত্ব = ৩/৮ = ৯/২৪\nমিতুর বাড়ি থেকে বিদ্যালয়ের দুরত্ব = ৫/১২ = ১০/২৪\nসবুজের বাড়ি থেকে মিতুর বাড়ির দূরত্ব = ৯/২৪ + ১০/২৪\n= (৯ + ১০)/২৪\n= ১৯/২৪\n∴ সবুজের বাড়ি থেকে মিতুর বাড়ির দূরত্ব ১৯/২৪ কিমি।"},{"n":"৫(খ)","q":"সবুজের বাড়ি বিদ্যালয় থেকে ৩/৮ কিমি পশ্চিমে অবস্থিত। মিতুর বাড়ি বিদ্যালয় থেকে ৫/১২ কি মি পূর্বে অবস্থিত। বিদ্যালয় থেকে কার বাড়ি নিকটবর্তী? সবুজ ও মিতুর বাড়ি থেকে বিদ্যালয়ের দূরত্বের পার্থক্য কত?","a":"ক হতে পাই,\nসবুজের বাড়ি থেকে বিদ্যালয়ের দুরত্ব = ৩/৮ = ৯/২৪\nমিতুর বাড়ি থেকে বিদ্যালয়ের দুরত্ব = ৫/১২ = ১০/২৪\nদুটো ভগ্নাংশের মধ্যে ৯/২৪ ভগ্নাংশের লব ছোট।\n∴ বিদ্যালয় থেকে সবুজের বাড়ি নিকটবর্তী।\nসবুজ ও মিতুর বাড়ি থেকে বিদ্যালয়ের দূরত্বের পার্থক্য\n= ১০/২৪ – ৯/২৪\n= (১০ – ৯)/২৪\n= ১/২৪\nউত্তর: বিদ্যালয় থেকে সবুজের বাড়ি নিকটবর্তী ও সবুজ ও মিতুর বাড়ি থেকে বিদ্যালয়ের দূরত্বের পার্থক্য ১/২৪ কিমি।"}]}},{"no":5,"title":"গুণিতক এবং গুণনীয়ক","q":{"short":[{"n":"১(১)","q":"লসাগু নির্ণয় করঃ ১৫,২১","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n৩)১৫,২১\n    ৫,৭\nনির্ণেয় লসাগু=৩×৫×৭=১০৫"},{"n":"১(২)","q":"লসাগু নির্ণয় করঃ ৩৫,২১","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n৭)৩৫,২১\n    ৫,৩\nনির্ণেয় লসাগু=৭×৫×৩=১০৫"},{"n":"১(৩)","q":"লসাগু নির্ণয় করঃ ২০,১২,২৫","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n২)২০,১২,২৫\n২)১০,৬,২৫\n৫)৫,৩,২৫\n    ১,৩,৫\nনির্ণেয় লসাগু=২×২×৫×৩×৫=৩০০"},{"n":"১(৪)","q":"লসাগু নির্ণয় করঃ ৯,১৬,১৮","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n২)৯,১৬,১৮\n৩)৯,৮,৯\n৩)৩,৮,৩\n     ১,৮,১\nনির্ণেয় লসাগু=২×৩×৩×৮=১৪৪"},{"n":"১(৫)","q":"লসাগু নির্ণয় করঃ ২০,১২,২৫,৩২","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n২)২০,১২,২৫,৩২\n২)১০,৬,২৫,১৬\n৫)৫,৩,২৫,৮\n    ১,৩,৫,৮\nনির্ণেয় লসাগু=২×২×৫×৩×৫×৮=২৪০০"},{"n":"২(১)","q":"গসাগু ণির্নয় করঃ ১২,১৮","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n২)১২,১৮\n৩)৬,৯\n     ২,৩\nনির্ণেয় গসাগু=২×৩=৬"},{"n":"২(২)","q":"গসাগু ণির্নয় করঃ ২৪,২৮","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n২)২৪,২৮\n২)১২,১৪\n      ৬,৭\nনির্ণেয় গসাগু=২×২=৪"},{"n":"২(৩)","q":"গসাগু ণির্নয় করঃ ৩৯,৫২","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n১৩)৩৯,৫২\n          ৩,৪\nনির্ণেয় গসাগু=১৩"},{"n":"২(৪)","q":"গসাগু ণির্নয় করঃ ৫৪,৩৬,৭২","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n২)৫৪,৩৬,৭২\n৩)২৭,১৮,৩৬\n৩)৯,৬,১২\n     ৩,২,৪\nনির্ণেয় গসাগু=২×৩×৩=১৮"},{"n":"২(৫)","q":"গসাগু ণির্নয় করঃ ২০,৩০,৩৬,৪৫","a":"প্রদত্ত সংখ্যাগুলোকে তাদের সাধারণ মৌলিক উৎপাদক দ্বারা ভাগ করি।\n১)২০,৩০,৩৬,৪৫\n   ২০,৩০,৩৬,৪৫\nনির্ণেয় গসাগু=১"},{"n":"৩","q":"একটি রাস্তায় কিছু গাছ এবং ল্যাম্পপোস্ট আছে। ২৫ মিটার পরপর গাছ এবং ২০ মিটার পরপর ল্যাম্পপোস্ট আছে। রাস্তার সগুরুতে গাছ ও ল্যাম্পপোস্ট একত্রে থাকলে কত মিটার পরপর গাছ ও ল্যাম্পপোস্ট পুনরায় একসাথে থাকবে?","a":"২৫ এবং ২০ এর লসাগুই হবে গাছ ও ল্যাম্পপোস্ট পুনরায় একসাথে থাকার দুরত্ত্ব।\n৫)২৫,২০\n    ৫,৪\nলসাগু=৫×৫×৪=১০০\nসুত্রাং নির্ণেয় দুরত্ব=১০০ মিটার।"},{"n":"৪","q":"তিনটি ভিন্ন রঙ এর ঘণ্টা আছে। লাল রঙ এর ঘণ্টা ১৮ মিনিট পরপর, হলুদ রঙ এর ঘণ্টা ১৫ মিনিট পরপর এবং সবুজ রঙ এর ঘণ্টা ১২ মিনিট পরপর বাজে। ঘণ্টাগুলো সন্ধ্যা ৬টায় একসাথে বাজলে, পুনরায় কখন একসাথে বাজবে।","a":"১৮,১৫,১২ এর লসাগুই হবে পুনরায় ঘণ্টাগুলো একসাথে বাজার সময়।\n২)১৮,১৫,১২\n৩)৯,১৫,৬\n     ৩,৫,২\nলসাগু=২×৩×৩×৫×২=১৮০\n১৮০ মিনিট=(১৮০÷৬০) ঘণ্টা=৩ ঘণ্টা\nঅর্থাৎ সন্ধ্যা ৬টা+৩ ঘণ্টা=রাত ৯ টায় ঘন্টাগুলো পুনরায় একসাথে বাজবে।"},{"n":"৬","q":"কোনো স্থানে ১০ জনের বেশি শিক্ষার্থী আছে। একজন শিক্ষক ৪২ টি কলা, ৮৪টি বিস্কুট এবং ১০৫টি চকলেট কোনো অবশিষ্ট না রেখে শিক্ষার্থীদের মধ্যে সমানভাগে ভাগ করে দিতে চান। কতজন শিক্ষার্থীর মধ্যে শিক্ষক কলা, বিস্কুট এবং চকলেট ভাগ করে দিতে পারবেন?","a":"৪২,৮৪,১০৫ এর গসাগুই হবে মোট শিক্ষার্থীর সংখ্যা।\n৩)৪২,৮৪,১০৫\n৭)১৪,২৮,৩৫\n      ২,৪,৫\nগসাগু=৩×৭=২১\nসুতরাং, শিক্ষার্থী সংখ্যা=২১ জন।"}],"other":[{"n":"৫(১)","q":"চিত্রে একটি আয়তকার মেঝের ছবি দেওয়া আছে। কোনো খালি জায়গা না রেখে আমরা ঘরের মেঝেতে বর্গাকার কার্পেট বসাতে চাই। [চিত্র — পাঠানো টেক্সটে ছবি নেই] মেঝেতে বিছানো যাবে এমন বর্গাকার কার্পেটের বৃহত্তমটির একবাহুর দৈর্ঘ্য নির্ণয় কর।","a":"মেঝেতে বিছানো যাবে এমন বর্গাকার কার্পেটের বৃহত্তমটির এক বাহুর দৈর্ঘ্য হবে ৪২ এবং ৩৬ এর গসাগু।\n২)৪২,৩৬\n৩)২১,১৮\n    ৭,৬\nগসাগু=২×৩=৬\nনির্ণেয় দৈর্ঘ্য=৬ মিটার।"},{"n":"৫(২)","q":"চিত্রে একটি আয়তকার মেঝের ছবি দেওয়া আছে। কোনো খালি জায়গা না রেখে আমরা ঘরের মেঝেতে বর্গাকার কার্পেট বসাতে চাই। [চিত্র — পাঠানো টেক্সটে ছবি নেই] সম্পূর্ণ মেঝে কার্পেট বিছানোর জন্য এরুপ কয়টি কার্পেট লাগবে?","a":"“১” হতে প্রাপ্ত, বৃহত্তম বর্গাকার কার্পেটের এক বাহুর দৈর্ঘ্য=৬ মিটার\nঅতএব, এর ক্ষেত্রফল=(৬×৬) বর্গমিটার=৩৬ বর্গমিটার\nআয়তাকার মেঝের ক্ষেত্রফল=(৪২×৩৬) বর্গমিটার=১৫১২ বর্গমিটার\nঅতএব, সম্পুর্ণ মেঝে কার্পেট বিছানোর জন্য কার্পেট লাগবে=১৫১২÷৩৬টি=৪২টি।"}]}},{"no":6,"title":"শতকরা","q":{"mcq":[{"n":"১(১)","q":"একটি সংখ্যার ৫০%, ৬ হলে সংখ্যাটি কত?","a":"ক) ১২","o":["১২","২৪","৩০","৪০"]},{"n":"১(২)","q":"নিচের কোনটি সঠিক?","a":"খ) ৯/২৫ = ৩৬%","o":["৯/২৫ = ৪৫%","৯/২৫ = ৩৬%","৯/২৫ = ১৮%","৯/২৫ = ৯%"]},{"n":"১(৩)","q":"চিত্রের কত % জায়গা রং করা আছে?","a":"গ) ৬০%","o":["৩%","১৫%","৬০%","৭৫%"]},{"n":"১(৪)","q":"৫০ লিটারের ১০% কত লিটার?","a":"ক) ৫","o":["৫","১০","৪০","৫০"]},{"n":"১(৫)","q":"১০০% এর অর্থ ১ হলে ১৫০% এর অর্থ কত?","a":"খ) ১.৫","o":["১৫","১.৫","০.১৫","০.০১৫"]}],"other":[{"n":"২","q":"পাশের ছবিতে মোট আমের শতকরা কত অংশ কাঁচা আম?","a":"ছবি থেকে গুনে দেখা যায়: মোট আম = ২৩ টি\nকাঁচা (সবুজ) আম = ১০টি\n২৩ টি আমের মধ্যে কাঁচা আম ৯ টি\n১টি আমের মধ্যে কাঁচা আম ৯/২৩ টি\n১০০টি আমের মধ্যে কাঁচা আম (৯ × ১০০)/২৩ = ৩৯.১৩ টি\nউত্তর: ৪০% কাঁচা আম।"}],"blank":[{"n":"৩(ক)","q":"২৪ জন লোক ৬০ জন লোকের ______ %","a":"৪০","e":"৬০ জনের মধ্যে ২৪ জন\n১ জনের মধ্যে ২৪/৬০ জন\n∴ ১০০ জনের মধ্যে (২৪ × ১০০)/৬০ = ৪০ জন।\n∴ ☐ = ৪০ জন।"},{"n":"৩(খ)","q":"৬৫০ টাকার ১৬৫% হলো ______ টাকা","a":"১০৭২.৫","e":"১০০ টাকার মধ্যে ১৬৫ টাকা\n১ টাকার মধ্যে ১৬৫/১০০ টাকা\n৬৫০ টাকার মধ্যে (১৬৫ × ৬৫০)/১০০ = ১০৭২.৫ টাকা।\n∴ ☐ = ১০৭২.৫ টাকা।"},{"n":"৩(গ)","q":"______ টি লিচুর ৫৬% হলো ৪২টি লিচু।","a":"৭৫","e":"এখানে,\n☐ × ৫৬% = ৪২ টি লিচু\nবা, ☐ = ৪২ ÷ ৫৬%\nবা, ☐ = ৪২ ÷ ৫৬/১০০\nবা, ☐ = ৪২ × ১০০/৫৬\nবা, ☐ = ৭৫ টি লিচু।\n∴ ☐ = ৭৫ টি লিচু।"}],"short":[{"n":"৪","q":"কোনো একটি কারখানায় একদিন ৯০ জন শ্রমিকের মধ্যে ৪০% অনুপস্থিত থাকল। ওই দিন কারখানায় উপস্থিত শ্রমিকের সংখ্যা কত?","a":"১০০ জন শ্রমিকের মধ্যে অনুপস্থিত ৪০ জন\n১ জন শ্রমিকের মধ্যে অনুপস্থিত ৪০/১০০ জন\n∴ ৯০ জন শ্রমিকের মধ্যে অনুপস্থিত (৪০ × ৯০)/১০০ = ৩৬ জন\nসুতরাং, উপস্থিত শ্রমিকের সংখ্যা = (৯০ – ৩৬) জন = ৫৪ জন।\nউত্তর: ৫৪ জন।"},{"n":"৫","q":"মনোবি চাকমা বাগান থেকে ১০ ডজন কলাসহ একটি কলার কাঁদি পাড়ল। পেড়ে দেখল কাঁদিতে ২৫% কলা পচা বা নষ্ট। তাহলে ভালো কলার সংখ্যা কত?","a":"আমরা জানি, ১ ডজন = ১২\n১০ ডজন কলা = (১০ × ১২) = ১২০টি কলা।\nপচা বা নষ্ট কলা ২৫%।\n১০০টি কলার মধ্যে নষ্ট হয় ২৫ টি\n১টি কলার মধ্যে নষ্ট হয় ২৫/১০০ টি\n∴ ১২০টি কলার মধ্যে নষ্ট হয় (২৫ × ১২০)/১০০ = ৩০ টি\nভালো কলার সংখ্যা = (১২০ – ৩০) টি = ৯০টি।\nউত্তর: ৯০টি।"},{"n":"৬","q":"বার্ষিক ১৩% মুনাফায় কোনো ব্যাংক থেকে কিছু টাকা ঋণ নিয়ে এক বছর পর ৮৮৪০ টাকা মুনাফা দেওয়া হলো। আসল কত ছিল?","a":"দেওয়া আছে, বার্ষিক ১৩% মুনাফা।\nমুনাফা ১৩ টাকা হলে আসল ১০০ টাকা\nমুনাফা ১ টাকা হলে আসল ১০০/১৩ টাকা\n∴ মুনাফা ৮৮৪০ টাকা হলে আসল (১০০ × ৮৮৪০)/১৩ টাকা = ৬৮০০০ টাকা।\nউত্তর: ৬৮০০০ টাকা।"},{"n":"৭","q":"ব্যাংক থেকে আসলের ওপর বার্ষিক ১২.৫% মুনাফায় ৩ বছরের জন্য ৫০০০০ টাকা ঋণ নেওয়া হলো। ৩ বছর পর মোট কত টাকা পরিশোধ করতে হবে?","a":"দেওয়া আছে, আসল ৫০,০০০ টাকা, বার্ষিক মুনাফা ১২.৫%।\n১০০ টাকার ১ বছরের মুনাফা ১২.৫ টাকা\n১ টাকার ১ বছরের মুনাফা ১২.৫/১০০ টাকা\n∴ ৫০,০০০ টাকার ১ বছরের মুনাফা (১২.৫ × ৫০০০০)/১০০ = ৬২৫০ টাকা\nসুতরাং, ৫০,০০০ টাকার ৩ বছরের মুনাফা = (৬২৫০ × ৩) টাকা = ১৮,৭৫০ টাকা।\nমোট পরিশোধ করতে হবে = (আসল + মুনাফা) = (৫০,০০০ + ১৮,৭৫০) টাকা = ৬৮,৭৫০ টাকা।\nউত্তর: ৬৮,৭৫০ টাকা।"},{"n":"৮","q":"একটি দোকানে ৩২০০ টাকার পণ্য ২০% কমে বিক্রয় করা হলো। পণ্যটির বিক্রয়মূল্য কত?","a":"ব্যাগের দাম ৩২০০ টাকা, ২০% কমে বিক্রয় করা হলো।\n১০০ টাকায় দাম কমে ২০ টাকা\n১ টাকায় দাম কমে ২০/১০০ টাকা\n∴ ৩২০০ টাকায় দাম কমে (২০ × ৩২০০)/১০০ = ৬৪০ টাকা\nব্যাগটির বিক্রয়মূল্য = (৩২০০ – ৬৪০) টাকা = ২৫৬০ টাকা।\nউত্তর: ২৫৬০ টাকা।"},{"n":"৯","q":"একজন বিক্রেতা কৃষকের কাছ থেকে সবজি কিনে ৪০% লাভে ৬৩০০ টাকায় বিক্রয় করলেন। সবজির ক্রয়মূল্য কত ছিল?","a":"৪০% লাভে বিক্রয় করা হয়েছে।\nঅর্থাৎ ক্রয়মূল্য ১০০ টাকা হলে বিক্রয়মূল্য (১০০ + ৪০) = ১৪০ টাকা।\nবিক্রয়মূল্য ১৪০ টাকা হলে ক্রয়মূল্য ১০০ টাকা\nবিক্রয়মূল্য ১ টাকা হলে ক্রয়মূল্য ১০০/১৪০ টাকা\n∴ বিক্রয়মূল্য ৬৩০০ টাকা হলে ক্রয়মূল্য (১০০ × ৬৩০০)/১৪০ = ৪৫০০ টাকা\nউত্তর: সবজির ক্রয়মূল্য ছিল ৪৫০০ টাকা।"},{"n":"১০","q":"১৫০ টাকায় একটি জিনিস ক্রয় করে কত দামে বিক্রয় করলে ৩০% লাভ হবে?","a":"১০০ টাকায় লাভ ৩০ টাকা\n১ টাকায় লাভ ৩০/১০০ টাকা\n১৫০ টাকায় লাভ (১৫০ × ৩০)/১০০ = ৪৫ টাকা\n∴ বিক্রয়মূল্য হতে হবে (১৫০ + ৪৫) টাকা = ১৯৫ টাকা।\nউত্তর: ১৯৫ টাকা।"},{"n":"১১","q":"উপকূলীয় একটি উপজেলার জনসংখ্যা ছিল ৭৬৩৫০ জন। সমুদ্র উপকূলে পানির উচ্চতা বৃদ্ধির কারণে ৪% মানুষ অন্যত্র চলে গেল। বর্তমানে ঐ উপজেলার জনসংখ্যা কত?","a":"উপজেলার মোট জনসংখ্যা ৭৬,৩৫০ জন। ৪% লোক চলে গেল।\n১০০ জন মানুষের মধ্যে চলে যায় ৪ জন\n১ জন মানুষের মধ্যে চলে যায় ৪/১০০ জন\n∴ ৭৬,৩৫০ জন মানুষের মধ্যে চলে যায় (৪ × ৭৬৩৫০)/১০০ = ৩০৫৪ জন\nবর্তমানে উপজেলার জনসংখ্যা = (৭৬,৩৫০ – ৩০৫৪) জন = ৭৩,২৯৬ জন।\nউত্তর: ৭৩,২৯৬ জন।"},{"n":"১২","q":"বার্ষিক ৫% মুনাফায় ৬০০ টাকা বিনিয়োগ করলে ৫ বছরে মুনাফাসহ আসল কত হবে?","a":"১০০ টাকার ১ বছরের মুনাফা ৫ টাকা\n১ টাকার ১ বছরের মুনাফা ৫/১০০ টাকা\n∴ ৬০০ টাকার ১ বছরের মুনাফা (৫ × ৬০০)/১০০ = ৩০ টাকা\nসুতরাং, ৫ বছরের মুনাফা = (৩০ × ৫) টাকা = ১৫০ টাকা।\n৫ বছর পর মুনাফাসহ আসল = (৬০০ + ১৫০) টাকা = ৭৫০ টাকা।\nউত্তর: ৭৫০ টাকা।"},{"n":"১৩(ক)","q":"একটি জুতার দোকানে ২৬% ছাড়ে জুতা বিক্রির ঘোষণা দেয়া হলো। মনোরঞ্জন দুই জোড়া জুতা ২৫৯০ ও ৩১০৮ টাকায় ক্রয় করল। প্রতি জোড়া জুতার প্রকৃত মূল্য কত?","a":"দেওয়া আছে,জুতার ওপর ছাড় = ২৬%\nঅর্থাৎ, প্রকৃত মূল্য ১০০ টাকা হলে, ছাড় দেওয়ার পর বিক্রয়মূল্য হয় (১০০ – ২৬) = ৭৪ টাকা।\nআমরা জানি,\n১ম জোড়া জুতার ক্ষেত্রে,\nবিক্রয়মূল্য ৭৪ টাকা হলে প্রকৃত মূল্য ১০০ টাকা\nবিক্রয়মূল্য ১ টাকা হলে প্রকৃত মূল্য ১০০/৭৪ টাকা\n∴ বিক্রয়মূল্য ২৫৯০ টাকা হলে প্রকৃত মূল্য (১০০ × ২৫৯০)/৭৪ টাকা = ৩৫০০ টাকা।\n২য় জোড়া জুতার ক্ষেত্রে,\nবিক্রয়মূল্য ৭৪ টাকা হলে প্রকৃত মূল্য ১০০ টাকা\nবিক্রয়মূল্য ১ টাকা হলে প্রকৃত মূল্য ১০০/৭৪ টাকা\n∴ বিক্রয়মূল্য ৩১০৮ টাকা হলে প্রকৃত মূল্য (১০০ × ৩১০৮)/৭৪ টাকা = ৪২০০ টাকা।\nউত্তর: ১ম জোড়া জুতার প্রকৃত মূল্য ৩৫০০ টাকা এবং ২য় জোড়া জুতার প্রকৃত মূল্য ৪২০০ টাকা।"},{"n":"১৩(খ)","q":"একটি জুতার দোকানে ২৬% ছাড়ে জুতা বিক্রির ঘোষণা দেয়া হলো। মনোরঞ্জন দুই জোড়া জুতা ২৫৯০ ও ৩১০৮ টাকায় ক্রয় করল। জুতা ক্রয় বাবদ তার কত টাকা সাশ্রয় হলো?","a":"মনোরঞ্জন মোট জুতা কিনলেন = (২৫৯০ + ৩১০৮) = ৫৬৯৮ টাকায়।\nক হতে পাই,\nজুতার মোট মূল্য = (৩৫০০ + ৪২০০) = ৭৭০০ টাকা।\nসাশ্রয় হলো = ৭৭০০ – ৫৬৯৮ = ২০০২ টাকা।\nউত্তর: ২০০২ টাকা।"},{"n":"১৪(ক)","q":"মতিন সাহেবের মাসিক আয় ৫৫৫০০ টাকা এবং তার মধ্য থেকে তিনি ১৩৮৭৫ টাকা বাড়ি ভাড়া বাবদ ব্যয় করেন। কবীর সাহেবের মাসিক আয় ৪৮০০০ টাকা এবং তিনি বাড়ি ভাড়া বাবদ ১৪৪০০ টাকা ব্যয় করেন। তাদের প্রত্যেকের আয়ের ওপর বাড়ি ভাড়া বাবদ ব্যয় শতকরায় প্রকাশ করি।","a":"মতিন সাহেব,\n৫৫৫০০ টাকায় ভাড়া দেন ১৩৮৭৫ টাকা\n১ টাকায় ভাড়া দেন ১৩৮৭৫/৫৫৫০০ টাকা\n∴ ১০০ টাকায় ভাড়া দেন (১৩৮৭৫ × ১০০)/৫৫৫০০ = ২৫ টাকা\n∴ মতিন সাহেব মোট আয়ের ওপর বাড়ি ভাড়া বাবদ ২৫% ব্যয় করেন।\nকবীর সাহেব,\n৪৮০০০ টাকায় ভাড়া দেন ১৪৪০০ টাকা\n১ টাকায় ভাড়া দেন ১৪৪০০/৪৮০০০ টাকা\n১০০ টাকায় ভাড়া দেন (১৪৪০০ × ১০০)/৪৮০০০ = ৩০ টাকা।\n∴ মতিন সাহেব মোট আয়ের ওপর বাড়ি ভাড়া বাবদ ৩০% ব্যয় করেন।"},{"n":"১৪(খ)","q":"মতিন সাহেবের মাসিক আয় ৫৫৫০০ টাকা এবং তার মধ্য থেকে তিনি ১৩৮৭৫ টাকা বাড়ি ভাড়া বাবদ ব্যয় করেন। কবীর সাহেবের মাসিক আয় ৪৮০০০ টাকা এবং তিনি বাড়ি ভাড়া বাবদ ১৪৪০০ টাকা ব্যয় করেন। দুইজনের মধ্যে কে বাড়ি ভাড়া বাবদ শতকরা হারে বেশি টাকা ব্যয় করেন?","a":"ক হতে পাই.\nমতিন সাহেবের ব্যয়ের হার ২৫% এবং কবীর সাহেবের ব্যয়ের হার ৩০%।\nএখানে, ২৫% < ৩০%\nমতিন সাহেব ব্যয়ের হার < কবীর সাহেবের ব্যয়ের হার\nসুতরাং, কবীর সাহেব বাড়ি ভাড়া বাবদ শতকরা হারে বেশি টাকা ব্যয় করেন।"}]}},{"no":7,"title":"গড়","q":{"mcq":[{"n":"১(১)","q":"২, ৪, ৫, ৭ ও ৯ সংখ্যাগুলোর গড় কত?","a":"গ) ৫.৪","o":["২৭","৫.৫","৫.৪","৫"]},{"n":"১(২)","q":"একজন ক্রিকেট খেলোয়াড়ের ৩টি ওয়ানডে ম্যাচের সংগৃহীত রান ৪৮, ৫২, ৫৩। তিনি গড়ে কত রান করেছেন?","a":"ঘ) ৫১ রান","o":["৪১ রান","৪৯ রান","৫০ রান","৫১ রান"]}],"short":[{"n":"২","q":"৫০টি সংখ্যার গড় ৩৮, দুইটি সংখ্যা ৪৫ ও ৫৫ বাদ দেয়া হলে বাকি সংখ্যাগুলোর গড় কত?","a":"৫০টি সংখ্যার গড় ৩৮\n৫০টি সংখ্যার সমষ্টি = (৩৮ × ৫০) = ১৯০০\nবাদ দেওয়া সংখ্যা দুটির যোগফল = (৪৫ + ৫৫) = ১০০\nবাকি (৫০ – ২) বা ৪৮টি সংখ্যার সমষ্টি = (১৯০০ – ১০০) = ১৮০০\nসুতরাং, বাকি ৪৮টি সংখ্যার গড় = ১৮০০ ÷ ৪৮ = ৩৭.৫।\nউত্তর: ৩৭.৫।"},{"n":"৩","q":"একজন ক্রিকেটারের ১৬টি ইনিংসের গড় রান ৩১.৭৫। পরবর্তী ৩টি ইনিংসে সে যদি ১০৮, ৩৪ এবং ৪৭ রান করে তবে তার গড় রান কত হবে?","a":"১৬ টি ইনিংসের গড় ৩১.৭৫ রান\n১৬টি ইনিংসের মোট রান = (৩১.৭৫ × ১৬) = ৫০৮ রান\nপরবর্তী ৩টি ইনিংসের মোট রান = (১০৮ + ৩৪ + ৪৭) = ১৮৯ রান\nমোট ইনিংস = (১৬ + ৩) = ১৯ টি\n১৯টি ইনিংসের মোট রান = (৫০৮ + ১৮৯) = ৬৯৭ রান\nসুতরাং, ১৯টি ইনিংসের গড় রান = ৬৯৭ ÷ ১৯ = ৩৬.৬৮ (প্রায়)।\nউত্তর: ৩৬.৬৮ (প্রায়)"},{"n":"৪","q":"শ্রেণিতে ২৪ জন শিক্ষার্থীর ও তাদের শিক্ষকের গড় বয়স ১৫ বছর। শিক্ষকের বয়স বাদ দিলে শুধু ২৪ জন শিক্ষার্থীর গড় বয়স ১ বছর হ্রাস পায়। তাহলে শিক্ষকের বয়স কত?","a":"এখানে মোট ব্যক্তি = (২৪ জন শিক্ষার্থী + ১ জন শিক্ষক) = ২৫ জন।\n২৫ জনের গড় বয়স ১৫ বছর\n২৫ জনের মোট বয়স = (১৫ × ২৫) = ৩৭৫ বছর\nশিক্ষককে বাদ দিলে গড় বয়স হয় = (১৫ – ১) = ১৪ বছর\n২৪ জন শিক্ষার্থীর মোট বয়স = (১৪ × ২৪) = ৩৩৬ বছর\nসুতরাং, শিক্ষকের বয়স = (৩৭৫ – ৩৩৬) বছর = ৩৯ বছর।\nউত্তর: ৩৯ বছর"},{"n":"৫","q":"একটি শ্রেণিতে ২০ জন শিক্ষার্থীর বয়সের গড় ১০ বছর। শ্রেণিতে আরও ১০ জন শিক্ষার্থী নতুন ভর্তি হওয়ায় তাদের বয়সের গড় ১১ বছর হলো। তাহলে নতুন শিক্ষার্থীদের বয়সের গড় কত?","a":"দেওয়া আছে:\n২০ জন শিক্ষার্থীর গড় বয়স ১০ বছর।\n২০ জন শিক্ষার্থীর মোট বয়স = (১০ × ২০) = ২০০ বছর\n১০ জন শিক্ষার্থী যোগ দিলে মোট শিক্ষার্থী সংখ্যা = ২০ + ১০ = ৩০ জন\n৩০ জন শিক্ষার্থীর মোট বয়স = (১১ × ৩০) = ৩৩০ বছর\nনতুন ১০ জন শিক্ষার্থীর মোট বয়স = (৩৩০ – ২০০) = ১৩০ বছর\nসুতরাং, নতুন শিক্ষার্থীদের গড় বয়স = ১৩০ ÷ ১০ = ১৩ বছর।\nউত্তর: ১৩ বছর।"},{"n":"৭(১)","q":"৬টি পেয়ারার ওজন যথাক্রমে ৫৮ গ্রাম, ৫০ গ্রাম, ৬০ গ্রাম, ৫২ গ্রাম, ৫৪ গ্রাম ও ৫৬ গ্রাম। পেয়ারাগুলোর গড় ওজন কত গ্রাম?","a":"পেয়ারাগুলোর ওজন: ৫৮, ৫০, ৬০, ৫২, ৫৪ ও ৫৬ গ্রাম।\n৬টি পেয়ারার মোট ওজন = ৫৮ + ৫০ + ৬০ + ৫২ + ৫৪ + ৫৬ = ৩৩০ গ্রাম\nগড় ওজন = ৩৩০ ÷ ৬ = ৫৫ গ্রাম।\nউত্তর: ৫৫ গ্রাম।"},{"n":"৭(২)","q":"৬টি পেয়ারার ওজন যথাক্রমে ৫৮ গ্রাম, ৫০ গ্রাম, ৬০ গ্রাম, ৫২ গ্রাম, ৫৪ গ্রাম ও ৫৬ গ্রাম। ১ম ৩টি পেয়ারার গড় ওজন কত?","a":"১ম ৩টির মোট ওজন = ৫৮ + ৫০ + ৬০ = ১৬৮ গ্রাম।\nগড় ওজন = ১৬৮ ÷ ৩ = ৫৬ গ্রাম।\nউত্তর: ৫৬ গ্রাম।"},{"n":"৭(৩)","q":"৬টি পেয়ারার ওজন যথাক্রমে ৫৮ গ্রাম, ৫০ গ্রাম, ৬০ গ্রাম, ৫২ গ্রাম, ৫৪ গ্রাম ও ৫৬ গ্রাম। ১ম ৩টি ও শেষ ৩টি পেয়ারার গড় ওজনের পার্থক্য কত গ্রাম?","a":"ক হতে, ১ম ৩টি পেয়ারার গড় ওজন ৫৬ গ্রাম।\nশেষ ৩টির মোট ওজন = ৫২ + ৫৪ + ৫৬ = ১৬২ গ্রাম\nশেষ ৩টির গড় ওজন = ১৬২ ÷ ৩ = ৫৪ গ্রাম\n∴ ১ম ৩টি ও শেষ ৩টি পেয়ারার গড় ওজনের পার্থক্য = (৫৬ – ৫৪) গ্রাম = ২ গ্রাম।\nউত্তর: গড় ওজনের পার্থক্য ২ গ্রাম।"}],"other":[{"n":"৬(১)","q":"নিচের ছকে ৫ জন শিক্ষার্থীর উচ্চতা দেয়া হলো। (ছক — নাম: সবুজ, রাখি, মকবুল, সামিয়া, রিতা; উচ্চতা (সেমি): ১৪২, ১৪৪, ১৩৭, ১৪৬, ১৪১) শিক্ষার্থীদের গড় উচ্চতা কত?","a":"মোট শিক্ষার্থী ৫ জন।\nমোট উচ্চতা = ১৪২ + ১৪৪ + ১৩৭ + ১৪৬ + ১৪১ = ৭১০ সেমি\nগড় উচ্চতা = ৭১০ ÷ ৫ = ১৪২ সেমি।\nউত্তর: ১৪২ সেমি।"},{"n":"৬(২)","q":"নিচের ছকে ৫ জন শিক্ষার্থীর উচ্চতা দেয়া হলো। (ছক — নাম: সবুজ, রাখি, মকবুল, সামিয়া, রিতা; উচ্চতা (সেমি): ১৪২, ১৪৪, ১৩৭, ১৪৬, ১৪১) সবচেয়ে বেশি উচ্চতার ২ জন শিক্ষার্থীর গড় উচ্চতা কত?","a":"সবচেয়ে বেশি উচ্চতা সামিয়া ও রাখি। তাদের দুজনের উচ্চতা ১৪৬ সেমি ও ১৪৪ সেমি।\n২ জনের মোট উচ্চতা = ১৪৬ + ১৪৪ = ২৯০ সেমি\n∴ গড় উচ্চতা = ২৯০ ÷ ২ = ১৪৫ সেমি।\nউত্তর: ১৪৫ সেমি।"},{"n":"৬(৩)","q":"নিচের ছকে ৫ জন শিক্ষার্থীর উচ্চতা দেয়া হলো। (ছক — নাম: সবুজ, রাখি, মকবুল, সামিয়া, রিতা; উচ্চতা (সেমি): ১৪২, ১৪৪, ১৩৭, ১৪৬, ১৪১) সবচেয়ে বেশি উচ্চতার ২ জন এবং সবচেয়ে কম উচ্চতার ২ জন শিক্ষার্থীর উচ্চতার গড়ের পার্থক্য কত?","a":"কম উচ্চতা মকবুল ও রিতা। মকবুলের উচ্চতা ১৩৭ সেমি ও রিতার উচ্চতা ১৪১ সেমি।\n২ জনের মোট উচ্চতা = ১৩৭ + ১৪১ = ২৭৮ সেমি\nমকবুল ও রিতার গড় উচ্চতা = ২৭৮ ÷ ২ = ১৩৯ সেমি\nক হতে পাই, সবচেয়ে বেশি উচ্চতার ২ জন শিক্ষার্থীর গড় উচ্চতা ১৪৫ সেমি।\n∴ সবচেয়ে বেশি উচ্চতার ২ জন এবং সবচেয়ে কম উচ্চতার ২ জন শিক্ষার্থীর উচ্চতার গড়ের পার্থক্য = (১৪৫ – ১৩৯)\nসেমি = ৬ সেমি\nউত্তর: ৬ সেমি।"}]}},{"no":8,"title":"পরিমাপ","q":{"mcq":[{"n":"১(১)","q":"দৈর্ঘ্য পরিমাপের ক্ষুদ্রতম একক কোনটি?","a":"খ) মিলিমিটার","o":["মিটার","মিলিমিটার","সেন্টিমিটার","হেক্টোমিটার"]},{"n":"১(২)","q":"আয়তাকার একটি খেলার মাঠের দৈর্ঘ্য ৫০ মিটার এবং প্রস্থ ৩০ মিটার। অপর দুই পাশের মোট দৈর্ঘ্য কত মিটার?","a":"ঘ) ৮০","o":["২০","৩০","৫০","৮০"]},{"n":"১(৩)","q":"আরিফের জন্মদিনে ১ কিলোগ্রাম ওজনের একটি কেক কেটে ১০ জন বন্ধুকে খাওয়ানো হলো। প্রত্যেক বন্ধুর ভাগে কতটুকু কেক পড়ল?","a":"গ) ১০ ডেকাগ্রাম","o":["১০০ ডেকাগ্রাম","১০০ ডেসিগ্রাম","১০ ডেকাগ্রাম","১০ হেক্টোগ্রাম"]}],"short":[{"n":"২","q":"রাজুর উচ্চতা ১.৩৫ মিটার এবং তার ভাইয়ের উচ্চতা ৯.৬ ডেসিমিটার। তাদের দুইজনের উচ্চতার পার্থক্য কত সেন্টিমিটার?","a":"রাজুর উচ্চতা ১.৩৫ মিটার এবং তার ভাইয়ের উচ্চতা ৯.৬ ডেসিমিটার।\nআমরা জানি, ১ মিটার = ১০০ সেন্টিমিটার এবং ১ ডেসিমিটার = ১০ সেন্টিমিটার।\nরাজুর উচ্চতা = (১.৩৫ × ১০০) সেমি = ১৩৫ সেমি।\nরাজুর ভাইয়ের উচ্চতা = (৯.৬ × ১০) সেমি = ৯৬ সেমি।\nউচ্চতার পার্থক্য = (১৩৫ – ৯৬) সেমি = ৩৯ সেমি।\nউত্তর: ৩৯ সেমি।"},{"n":"৩","q":"একজন দর্জির কাছে ৩৭৫ ডেসিমিটার কাপড় আছে। এখন তিনি যদি এই কাপড় দিয়ে ১৫টি শার্ট তৈরি করতে চান তবে প্রতিটি শার্টের জন্য কত সেন্টিমিটার কাপড় ব্যবহার করতে পারবেন?","a":"দেওয়া আছে: ৩৭৫ ডেসিমিটার কাপড় দিয়ে ১৫টি শার্ট তৈরি করা হবে।\nআমরা জানি, ১ ডেসিমিটার = ১০ সেন্টিমিটার।\n৩৭৫ ডেসিমিটার = ৩৭৫ × ১০ সেমি = ৩৭৫০ সেমি।\n১৫টি শার্টের জন্য লাগে ৩৭৫০ সেমি কাপড়\n১টি শার্টের জন্য লাগে = (৩৭৫০ ÷ ১৫) সেমি = ২৫০ সেমি কাপড়।\nউত্তর: ২৫০ সেমি।"},{"n":"৪","q":"মাহফুজ বাজার থেকে ৪.৫ কেজি চাল, ৮ হেক্টোগ্রাম সবজি এবং ২৪০০ গ্রাম মুরগির মাংস কিনল। সে মোট কত কেজি বাজার করল?","a":"দেওয়া আছে: চাল ৪.৫ কেজি, সবজি ৮ হেক্টোগ্রাম, মুরগির মাংস ২৪০০ গ্রাম।\nআমরা জানি, ১০ হেক্টোগ্রাম = ১ কেজি\nসবজি ৮ হেক্টোগ্রাম = (৮ ÷ ১০) কেজি = ০.৮ কেজি\nআবার, ১০০০ গ্রাম = ১ কেজি\nমুরগির মাংস ২৪০০ গ্রাম = (২৪০০ ÷ ১০০০) কেজি = ২.৪ কেজি\nমোট বাজার = (৪.৫ + ০.৮ + ২.৪) কেজি = ৭.৭ কেজি।\nউত্তর: ৭.৭ কেজি।"},{"n":"৫","q":"৮ জন লোকের ওজন ৪৫১.২ কেজি। তাহলে তাদের গড় ওজন কত হেক্টোগ্রাম হবে?","a":"দেওয়া আছে, ৮ জন লোকের মোট ওজন ৪৫১.২ কেজি।\n১ কেজি = ১০ হেক্টোগ্রাম।\n৪৫১.২ কেজি = (৪৫১.২ × ১০) হেক্টোগ্রাম = ৪৫১২ হেক্টোগ্রাম।\n৮ জনের মোট ওজন ৪৫১২ হেক্টোগ্রাম।\n৮ জনের গড় ওজন = (৪৫১২ ÷ ৮) হেক্টোগ্রাম = ৫৬৪ হেক্টোগ্রাম।\nউত্তর: ৫৬৪ হেক্টোগ্রাম।"},{"n":"৬","q":"বোতলে ৭৫ সেন্টিলিটার সরিষার তেল ছিল। শান্তর মা সেখান থেকে রান্নার সময় ১৭০ মিলিলিটার তেল ব্যবহার করে ফেললেন। তাহলে ঐ বোতলে আর কত লিটার তেল অবশিষ্ট রইল?","a":"দেওয়া আছে, তেল ছিল ৭৫ সেন্টিলিটার, ব্যবহার করা হলো ১৭০ মিলিলিটার।\nআমরা জানি, ১ সেন্টিলিটার = ১০ মিলিলিটার।\n৭৫ সেন্টিলিটার = (৭৫ × ১০) মিলি = ৭৫০ মিলি।\nবোতলে তেল ছিল = ৭৫০ মিলি।\nব্যবহার করা হলো = ১৭০ মিলি।\nঅবশিষ্ট রইল = (৭৫০ – ১৭০) মিলি = ৫৮০ মিলি।\nআবার, ১০০০ মিলি = ১ লিটার\n৫৮০ মিলি = (৫৮০ ÷ ১০০০) লিটার = ০.৫৮ লিটার।\nউত্তর: ০.৫৮ লিটার তেল অবশিষ্ট রইলো।"},{"n":"৭","q":"একটি দোকানে ৮ দিনে ২০ লিটার পানির বোতল বিক্রি হয়। তাহলে ঐ দোকানে দৈনিক গড়ে কত ডেসিলিটার পানি বিক্রি হয়?","a":"আমরা জানি, ১ লিটার = ১০ ডেসিলিটার\n২০ লিটার = ২০ × ১০ = ২০০ ডেসিলিটার\nমোট পানি = ২০০ ডেসিলিটার\n৮ দিনে বিক্রি হয় ২০০ ডেসিলিটার।\n১ দিনে বিক্রি হয় = (২০০ ÷ ৮) ডেসিলিটার = ২৫ ডেসিলিটার।\nউত্তর: ২৫ ডেসিলিটার।"},{"n":"৮","q":"রাসেল বাজার থেকে ২৫০ মিলি’র এক প্যাকেট দুধ কিনল। এখন যদি সে এ রকম আরও ৪০ প্যাকেট দুধ কেনে তবে সে কত লিটার দুধ পাবে?","a":"মোট প্যাকেট সংখ্যা = (৪০ + ১) = ৪১টি।\n১টি প্যাকেটে আছে ২৫০ মিলি দুধ\n৪১টি প্যাকেটে আছে = (২৫০ × ৪১) মিলি = ১০২৫০ মিলি দুধ।\n১০০০ মিলি = ১ লিটার\n১০২৫০ মিলি = (১০২৫০ ÷ ১০০০) লিটার = ১০.২৫ লিটার।\nউত্তর: ১০.২৫ লিটার।"},{"n":"৯(ক)","q":"মীম প্রতি মিনিটে ৪২ মিটার হাঁটে এবং মিহির প্রতি সেকেন্ডে ৮০ সেমি হাঁটে। তারা দুইজন প্রতিদিন ৩.৬ কিমি হাঁটে। মীমের হাঁটতে কত মিনিট সময় লাগে?","a":"আমরা জানি, ১ কিমি = ১০০০ মিটার\n৩.৬ কিমি = (৩.৬ × ১০০০) মিটার = ৩৬০০ মিটার।\nমীম ৪২ মিটার হাঁটে ১ মিনিটে\n১ মিটার হাঁটে ১/৪২ মিনিটে\n৩৬০০ মিটার হাঁটে ৩৬০০/৪২ মিনিটে = ৮৫.৭১ মিনিট।\nউত্তর: মীমের হাঁটতে ৮৫.৭১ মিনিট সময় লাগে।"},{"n":"৯(খ)","q":"মীম প্রতি মিনিটে ৪২ মিটার হাঁটে এবং মিহির প্রতি সেকেন্ডে ৮০ সেমি হাঁটে। তারা দুইজন প্রতিদিন ৩.৬ কিমি হাঁটে। মিহিরের হাঁটতে কত মিনিট সময় লাগে?","a":"মিহির ১ সেকেন্ডে হাঁটে ৮০ সেমি।\nমিহির ১ মিনিট বা ৬০ সেকেন্ডে হাঁটে = (৮০ × ৬০) সেমি = ৪৮০০ সেমি।\nআমরা জানি, ১০০ সেমি = ১ মিটার\n৪৮০০ সেমি = (৪৮০০ ÷ ১০০) মিটার = ৪৮ মিটার।\n∴ মিহির ১ মিনিটে ৪৮ মিটার হাঁটে।\nবা, মিহির ৪৮ মিটার হাঁটে ১ মিনিটে\nমিহির ১ মিটার হাঁটে ১/৪৮ মিনিটে\nমিহির ৩৬০০ মিটার হাঁটে ৩৬০০/৪৮ মিনিটে = ৭৫ মিনিট।\nউত্তর: মিহিরের হাঁটতে ৭৫ মিনিট সময় লাগে।"}]}},{"no":9,"title":"জ্যামিতি","q":{"blank":[{"n":"১(১)","q":"খালি ঘরে সঠিক শব্দ বসাই। সামান্তরিকের ক্ষেত্রফল = ______ × ______","a":"ভূমি, উচ্চতা","e":"সামান্তরিকের ক্ষেত্রফল = ভূমি × উচ্চতা"},{"n":"১(২)","q":"খালি ঘরে সঠিক শব্দ বসাই। ত্রিভুজের ক্ষেত্রফল = ______ × ______ ÷ ২","a":"ভূমি, উচ্চতা","e":"ত্রিভুজের ক্ষেত্রফল = ভূমি × উচ্চতা ÷ ২"}],"other":[{"n":"২(১)","q":"নিচের আকৃতিগুলোর ক্ষেত্রফল নির্ণয় করি। [১ — চিত্র/ছবি-নির্ভর]","a":"ত্রিভুজের ভূমি ৫ সেমি এবং উচ্চতা ৪ সেমি।\n∴ ত্রিভুজের ক্ষেত্রফল\n= (ভূমি × উচ্চতা) ÷ ২\n= (৫ × ৪) ÷ ২\n= ২০ ÷ ২ = ১০ বর্গ সেমি।\nউত্তর: ১০ বর্গ সেমি।"},{"n":"২(২)","q":"নিচের আকৃতিগুলোর ক্ষেত্রফল নির্ণয় করি। [২ — চিত্র/ছবি-নির্ভর]","a":"ত্রিভুজের ভূমি ৯ সেমি এবং উচ্চতা ৬ সেমি।\n∴ ত্রিভুজের ক্ষেত্রফল\n= (ভূমি × উচ্চতা) ÷ ২\n= (৯ × ৬) ÷ ২\n= ৫৪ ÷ ২ = ২৭ বর্গ সেমি।\nউত্তর: ২৭ বর্গ সেমি।"},{"n":"২(৩)","q":"নিচের আকৃতিগুলোর ক্ষেত্রফল নির্ণয় করি। [৩ — চিত্র/ছবি-নির্ভর]","a":"সামন্তরিকটি ভূমি ৫ সেমি এবং উচ্চতা ৬ সেমি।\n∴ সামন্তরিকের ক্ষেত্রফল\n= (ভূমি × উচ্চতা)\n=৫×৬\n= ৩০ বর্গ সেমি।\nউত্তর: ৩০ বর্গ সেমি।"},{"n":"২(৪)","q":"নিচের আকৃতিগুলোর ক্ষেত্রফল নির্ণয় করি। [৪ — চিত্র/ছবি-নির্ভর]","a":"সামন্তরিকটি ভূমি ২ সেমি এবং উচ্চতা ১ সেমি।\n∴ সামন্তরিকের ক্ষেত্রফল\n= (ভূমি × উচ্চতা)\n= ২ × ১০\n= ২০ বর্গ সেমি।\nউত্তর: ২০ বর্গ সেমি।"},{"n":"৬(১)","q":"নিচের আকৃতিগুলোর রঙিন অংশের ক্ষেত্রফল নির্ণয় করি। [১ — চিত্র/ছবি-নির্ভর]","a":"ছবিটিতে একটি আয়তের ভেতর রঙিন ত্রিভুজ আছে।\nত্রিভুজটির ভূমি ৯ সেমি এবং উচ্চতা ৫ সেমি।\n∴ ত্রিভুজটির ক্ষেত্রফল\n= (ভূমি × উচ্চতা) ÷ ২\n= (৯ × ৫) ÷ ২ বর্গ সেমি\n= ৪৫ ÷ ২ বর্গ সেমি\n= ২২.৫ বর্গ সেমি।\nআয়তক্ষেত্রের ক্ষেত্রফল\n= দৈঘ্য × প্রস্থ\n= ৯ × ৫ বর্গ সেমি\n= ৪৫ বর্গ সেমি\nরঙিন অংশের ক্ষেত্রফল\n= আয়তক্ষেত্রের ক্ষেত্রফল – ত্রিভুজটির ক্ষেত্রফল\n= (৪৫ – ২২.৫) বর্গ সেমি\n= ২২.৫ বর্গ সেমি\nউত্তর: রঙিন অংশের ক্ষেত্রফল ২২.৫ বর্গ সেমি।"},{"n":"৬(২)","q":"নিচের আকৃতিগুলোর রঙিন অংশের ক্ষেত্রফল নির্ণয় করি। [২ — চিত্র/ছবি-নির্ভর]","a":"ত্রিভুজটির ভূমি ১০ সেমি এবং উচ্চতা ১২ সেমি।\n∴ ত্রিভুজটির ক্ষেত্রফল\n= (ভূমি × উচ্চতা) ÷ ২\n= (১০ × ১২) ÷ ২ বর্গ সেমি\n= ১২০ ÷ ২ বর্গ সেমি\n= ৬০ বর্গ সেমি\nরঙহীন ত্রিভুজটির ভূমি ১০ সেমি এবং উচ্চতা ৫ সেমি।\n∴ রঙহীন ত্রিভুজটির ক্ষেত্রফল\n= (ভূমি × উচ্চতা) ÷ ২\n= (১০ × ৫) ÷ ২ বর্গ সেমি\n= ৫০ ÷ ২ বর্গ সেমি\n= ২৫ বর্গ সেমি\nরঙিন অংশের ক্ষেত্রফল\n= পুরো ত্রিভুজটির ক্ষেত্রফল – রঙহীন ত্রিভুজটির ক্ষেত্রফল\n= (৬০ – ২৫) বর্গ সেমি\n= ৩৫ বর্গ সেমি\nউত্তর: রঙিন অংশের ক্ষেত্রফল ৩৫ বর্গ সেমি।"},{"n":"৭","q":"নিচের চিত্রের ঘরটির রং করা অংশের সম্পূর্ণ ক্ষেত্রফল নির্ণয় করি।","a":"ঘরটির রং করা অংশগুলো মূলত আয়ত ও বর্গ ক্ষেত্র। আমরা আলাদাভাবে এদের ক্ষেত্রফল বের করে যোগ\nকরলেই সম্পূর্ণ ক্ষেত্রফল পেয়ে যাব।\n১ম দেয়াল,\nদৈঘ্য = ৫ মিটার ও প্রস্থ = ৫ মিটার। যা একটি বর্গ।\n∴ বর্গক্ষেত্রের ক্ষেত্রফল\n= (দৈঘ্য × প্রস্থ)\n= (৫ × ৫) বর্গ মিটার\n= ২৫ বর্গ মিটার\n২য় দেয়াল,\nদৈঘ্য = ১০ মিটার ও প্রস্থ = ৫ মিটার। যা একটি আয়তক্ষেত্র।\n∴ আয়তক্ষেত্রের ক্ষেত্রফল = (দৈঘ্য × প্রস্থ)\n= (১০ × ৫) বর্গ মিটার\n= ৫০ বর্গ মিটার\n৩য় দেয়াল,\nদৈঘ্য = ১০ মিটার ও প্রস্থ = ৪ মিটার। যা একটি আয়তক্ষেত্র।\n∴ আয়তক্ষেত্রের ক্ষেত্রফল = (দৈঘ্য × প্রস্থ)\n= (১০ × ৪) বর্গ মিটার\n= ৪০ বর্গ মিটার\n∴ রং করা অংশের সম্পূর্ণ ক্ষেত্রফল\n= (১ম দেয়াল + ২য় দেয়াল + ৩য় দেয়াল)\n= (২৫ + ৫০ + ৪০) বর্গমিটার\n= ১১৫ বর্গমিটার\nউত্তর: রং করা অংশের সম্পূর্ণ ক্ষেত্রফল ৮৫ বর্গমিটার।"}],"short":[{"n":"৩","q":"একটি আয়তাকার জমির প্রস্থ ৮৫ মিটার এবং দৈর্ঘ্য ১০৫ মিটার। জমিটির ক্ষেত্রফল কত?","a":"দেওয়া আছে, দৈর্ঘ্য ১০৫ মিটার এবং প্রস্থ ৮৫ মিটার।\nআমরা জানি, আয়তাকার ক্ষেত্রের ক্ষেত্রফল = দৈর্ঘ্য × প্রস্থ\nসুতরাং, জমির ক্ষেত্রফল\n= দৈর্ঘ্য × প্রস্থ\n= (১০৫ × ৮৫) বর্গ মিটার\n= ৮৯২৫ বর্গ মিটার।\nউত্তর: ৮৯২৫ বর্গ মিটার।"},{"n":"৪","q":"একটি বর্গাকার বাড়ির প্রস্থ ৫৫ মিটার এবং এর ক্ষেত্রফল ৩০২৫ বর্গ মিটার। বাড়িটির দৈর্ঘ্য কত মিটার?","a":"আমরা জানি, বর্গক্ষেত্রের দৈঘ্য ও প্রস্থ সমান হয়। দেওয়া আছে বর্গাকার বাড়িটির প্রস্থ ৫৫ মিটার। বাড়িটি\nবর্গাকার হওয়ায় বাড়িটির দৈঘ্য = প্রস্থ হবে।\n∴ বাড়িটির দৈঘ্য ৫৫ মিটার।\nঅন্যভাবে,\nদেওয়া আছে, বাড়িটির প্রস্থ ৫৫ মিটার এবং ক্ষেত্রফল ৩০২৫ বর্গ মিটার।\n্আমরা জানি, বর্গের ক্ষেত্রফল = দৈঘ্য × প্রস্থ\nবা, ৩০২৫ = দৈঘ্য × ৫৫\nবা, দৈঘ্য × ৫৫ = ৩০২৫\nবা, দৈঘ্য = ৩০২৫ ÷ ৫৫\n∴ দৈঘ্য = ৫৫ মিটার\nউত্তর: বাড়িটির দৈঘ্য ৫৫ মিটার।"},{"n":"৫","q":"একটি ত্রিভুজাকৃতি ডিজাইনের উচ্চতা ০.৮ মি এবং এর ক্ষেত্রফল ১.২ বর্গ মি হলে এর ভূমি কত মি?","a":"দেওয়া আছে. ত্রিভুজাকৃতি ডিজাইনের উচ্চতা ০.৮ মি এবং ক্ষেত্রফল ১.২ বর্গ মি।\nআমরা জানি, ত্রিভুজের ক্ষেত্রফল = (ভূমি × উচ্চতা) ÷ ২\nবা, (ভূমি × উচ্চতা) ÷ ২ = ক্ষেত্রফল\nবা, ভূমি × উচ্চতা = ক্ষেত্রফল × ২\nবা, ভূমি = (ক্ষেত্রফল × ২) ÷ উচ্চতা\nবা, ভূমি = (১.২ × ২) ÷ ০.৮\nবা, ভূমি = ২.৪ ÷ ০.৮\nবা, ভূমি = ৩ মিটার।\nউত্তর: ৩ মিটার।"}]}},{"no":10,"title":"উপাত্ত বিন্যস্তকরণ","q":{"short":[{"n":"১(ক)","q":"৫ম শ্রেণির শিক্ষার্থীদের ইংরেজি বিষয়ে প্রাপ্ত নম্বর হলো ৫০, ৩৪, ৯৫, ৮০, ৪৮, ৫৫, ৮৭, ৪০, ৩৫, ৭৬, ৮২, ৬৪, ৪৩, ৫২, ৯২, ৩৮, ৮৮, ৭২, ৮৫, ৯৭, ৮৩, ৬৫, ৪০, ৫৪, ৮৮, ৯৯, ৬১, ৮১, ৯৫, ৭৭। উপাত্তগুলো ক্রমানুসারে সাজাই।","a":"উপাত্তগুলোকে ছোট থেকে বড় (ঊর্ধ্বক্রমে) সাজালে পাই:\n৩৪, ৩৫, ৩৮, ৪০, ৪০, ৪৩, ৪৮, ৫০, ৫২, ৫৪, ৫৫, ৬১, ৬৪, ৬৫, ৭২, ৭৬, ৭৭, ৮০, ৮১, ৮২, ৮৩, ৮৫, ৮৭, ৮৮, ৮৮, ৯২, ৯৫, ৯৫, ৯৭, ৯৯।"},{"n":"১(খ)","q":"৫ম শ্রেণির শিক্ষার্থীদের ইংরেজি বিষয়ে প্রাপ্ত নম্বর হলো ৫০, ৩৪, ৯৫, ৮০, ৪৮, ৫৫, ৮৭, ৪০, ৩৫, ৭৬, ৮২, ৬৪, ৪৩, ৫২, ৯২, ৩৮, ৮৮, ৭২, ৮৫, ৯৭, ৮৩, ৬৫, ৪০, ৫৪, ৮৮, ৯৯, ৬১, ৮১, ৯৫, ৭৭। প্রাপ্ত সর্বোচ্চ ও সর্বনিম্ন নম্বর কত?","a":"উপরের সাজানো উপাত্ত থেকে দেখতে পাচ্ছি:\nসবচেয়ে ছোট সংখ্যাটি হলো সর্বনিম্ন নম্বর: ৩৪\nসবচেয়ে বড় সংখ্যাটি হলো সর্বোচ্চ নম্বর: ৯৯"},{"n":"৪(ক)","q":"আমাদের শ্রেণির প্রত্যেক শিক্ষার্থীর ওজন (কেজি) পরিমাপ করি। প্রাপ্ত উপাত্তগুলোকে মানের ক্রমানুসারে সাজাই।","a":"আমাদের শ্রেণিতে ৩৬ জন শিক্ষার্থী রয়েছে। ৩৬ জন শিক্ষার্থীর ওজন পরিমাপ করে পাই,\n৩২, ৩৫, ২৮, ৪০, ৪২, ৩৬, ৩০, ৩১, ৩৮, ৩৯, ৪৫, ২৯, ৩৩, ৩৪, ৩৭, ৪১, ৪৪, ২৭, ৩৫, ৩৬, ৩২, ৩৮, ৩০, ৩১, ৩৩, ৩৯, ৪০, ৪৩, ২৮, ৩৫, ৩৭, ৩৪, ৩৬, ৩১, ৩২, ৩৮।\nপ্রাপ্ত উপাত্তগুলোকে মানের ক্রমানুসারে সাজিয়ে পাই:\n২৭, ২৮, ২৮, ২৯, ৩০, ৩০, ৩১, ৩১, ৩১, ৩২, ৩২, ৩২, ৩৩, ৩৩, ৩৪, ৩৪, ৩৫, ৩৫, ৩৫, ৩৬, ৩৬, ৩৬, ৩৭, ৩৭, ৩৮, ৩৮, ৩৮, ৩৯, ৩৯, ৪০, ৪০, ৪১, ৪২, ৪৩, ৪৪, ৪৫।"},{"n":"৪(ঘ)","q":"আমাদের শ্রেণির প্রত্যেক শিক্ষার্থীর ওজন (কেজি) পরিমাপ করি। কোন শ্রেণি ব্যবধানে শিক্ষার্থী সংখ্যা সবচেয়ে বেশি?","a":"আমাদের তৈরি করা সারণিটিতে লক্ষ করলে দেখা যায়, সবচেয়ে বেশি শিক্ষার্থী আছে ১৩ জন।\nএই ১৩ জন শিক্ষার্থী রয়েছে ৩১-৩৫ শ্রেণি ব্যবধানে।\nসুতরাং, ৩১-৩৫ শ্রেণি ব্যবধানে শিক্ষার্থী সংখ্যা সবচেয়ে বেশি।"}],"other":[{"n":"১(গ)","q":"৫ম শ্রেণির শিক্ষার্থীদের ইংরেজি বিষয়ে প্রাপ্ত নম্বর হলো ৫০, ৩৪, ৯৫, ৮০, ৪৮, ৫৫, ৮৭, ৪০, ৩৫, ৭৬, ৮২, ৬৪, ৪৩, ৫২, ৯২, ৩৮, ৮৮, ৭২, ৮৫, ৯৭, ৮৩, ৬৫, ৪০, ৫৪, ৮৮, ৯৯, ৬১, ৮১, ৯৫, ৭৭। ১০ শ্রেণি ব্যবধান ধরে একটি সারণি তৈরি করি।","a":"এখানে সর্বনিম্ন নম্বর ৩৪ এবং সর্বোচ্চ নম্বর ৯৯।\nশ্রেণি ব্যবধান (প্রাপ্ত নম্বর) | ট্যালি চিহ্ন | শিক্ষার্থীর সংখ্যা (গণসংখ্যা)\n৩৪ – ৪৩ | 𝍸 | | ৬\n৪৪ – ৫৩ | ||| | ৩\n৫৪ – ৬৩ | ||| | ৩\n৬৪ – ৭৩ | ||| | ৩\n৭৪ – ৮৩ | 𝍸 | | ৬\n৮৪ – ৯৩ | 𝍸  | ৫\n৯৪ – ১০৩ | |||| | ৪\nমোট | | ৩০"},{"n":"১(ঘ)","q":"৫ম শ্রেণির শিক্ষার্থীদের ইংরেজি বিষয়ে প্রাপ্ত নম্বর হলো ৫০, ৩৪, ৯৫, ৮০, ৪৮, ৫৫, ৮৭, ৪০, ৩৫, ৭৬, ৮২, ৬৪, ৪৩, ৫২, ৯২, ৩৮, ৮৮, ৭২, ৮৫, ৯৭, ৮৩, ৬৫, ৪০, ৫৪, ৮৮, ৯৯, ৬১, ৮১, ৯৫, ৭৭। সারণির উপর ভিত্তি করে আয়তলেখ আঁকি।","a":"আয়তলেখ আঁকা হলো: [আয়তলেখটি PDF-এ ছবি হিসেবে আছে, লেখা হিসেবে নেই]"},{"n":"২(ক)","q":"নিচের আয়তলেখটি ৪র্থ শ্রেণির শিক্ষার্থীদের গণিতে প্রাপ্ত নম্বরের উপর ভিত্তি করে আঁকা হয়েছে। [আয়তলেখ চিত্র PDF-এ ছবি হিসেবে আছে] ৪র্থ শ্রেণিতে মোট কতজন শিক্ষার্থী আছে?","a":"আয়তলেখ থেকে আমরা বিভিন্ন নম্বর শ্রেণিতে শিক্ষার্থীর সংখ্যাগুলো বের করে যোগ করলেই মোট শিক্ষার্থীর সংখ্যা পেয়ে যাব।\nস্তম্ভগুলোর উচ্চতা অনুযায়ী শিক্ষার্থীর সংখ্যা হলো:\n৩১-৪০ নম্বর পেয়েছে: ৩ জন\n৪১-৫০ নম্বর পেয়েছে: ৪ জন\n৫১-৬০ নম্বর পেয়েছে: ৫ জন\n৬১-৭০ নম্বর পেয়েছে: ৭ জন\n৭১-৮০ নম্বর পেয়েছে: ৩ জন\n৮১-৯০ নম্বর পেয়েছে: ৬ জন\n৯১-১০০ নম্বর পেয়েছে: ২ জন\n∴ ৪র্থ শ্রেণিতে মোট শিক্ষার্থী আছে = (৩ + ৪ + ৫ + ৭ + ৩ + ৬ + ২) জন = ৩০ জন।\nউত্তর: ৩০ জন।"},{"n":"২(খ)","q":"নিচের আয়তলেখটি ৪র্থ শ্রেণির শিক্ষার্থীদের গণিতে প্রাপ্ত নম্বরের উপর ভিত্তি করে আঁকা হয়েছে। [আয়তলেখ চিত্র PDF-এ ছবি হিসেবে আছে] কোন শ্রেণি ব্যবধানে শিক্ষার্থী সবচেয়ে বেশি?","a":"আয়তলেখে সবচেয়ে উঁচু স্তম্ভটি হলো ৭ ঘর সমান উঁচু। আর এটি রয়েছে ৬১-৭০ শ্রেণি ব্যবধানে।\nসুতরাং, ৬১-৭০ শ্রেণি ব্যবধানে শিক্ষার্থী সবচেয়ে বেশি।"},{"n":"২(গ)","q":"নিচের আয়তলেখটি ৪র্থ শ্রেণির শিক্ষার্থীদের গণিতে প্রাপ্ত নম্বরের উপর ভিত্তি করে আঁকা হয়েছে। [আয়তলেখ চিত্র PDF-এ ছবি হিসেবে আছে] উপরের আয়তলেখ থেকে একটি সারণি তৈরি করি।","a":"আয়তলেখ থেকে সারণি তৈরি করা হলো:\nশ্রেণি ব্যবধান | ট্যালি চিহ্ন | গণসংখ্যা\n৩১-৪০ | ||| | ৩\n৪১-৫০ | |||| | ৪\n৫১-৬০ | 𝍸  | ৫\n৬১-৭০ | 𝍸 || | ৭\n৭১-৮০ | ||| | ৩\n৮১-৯০ | 𝍸 | | ৬\n৯১-১০০ | || | ২\nমোট | | ৩০"},{"n":"২(ঘ)","q":"নিচের আয়তলেখটি ৪র্থ শ্রেণির শিক্ষার্থীদের গণিতে প্রাপ্ত নম্বরের উপর ভিত্তি করে আঁকা হয়েছে। [আয়তলেখ চিত্র PDF-এ ছবি হিসেবে আছে] ৫১-৬০ শ্রেণি ব্যবধানে শিক্ষার্থী সংখ্যা শতকরা কত?","a":"মোট শিক্ষার্থী = ৩০ জন।\n৫১-৬০ শ্রেণিতে আছে = ৫ জন।\nশতকরা = ৫/৩০ × ১০০% = ১৬.৬৭ % (প্রায়)\n∴ ৫১-৬০ শ্রেণি ব্যবধানে শিক্ষার্থী সংখ্যা শতকরা ১৬.৬৭ জন (প্রায়)।\nউত্তর: ১৬.৬৭ %।"},{"n":"৩(ক)","q":"একটি বিদ্যালয়ে ৫০০ জন শিক্ষার্থী আছে। প্রধান শিক্ষক সবাইকে নিয়ে পিকনিকে যেতে চান। শিক্ষার্থীরা চিড়িয়াখানা, শিশুপার্ক এবং জাদুঘর এই তিনটির মধ্যে কোনটিতে কতজন যেতে ইচ্ছুক তা নিচের পাই চার্টে দেখানো হলো। [পাই চার্ট PDF-এ ছবি হিসেবে আছে] কতজন শিক্ষার্থী চিড়িয়াখানায় যেতে ইচ্ছুক?","a":"চিত্রে দেওয়া আছে চিড়িয়াখানায় যেতে চায় ১২%।\nঅর্থাৎ, ১০০ জনের মধ্যে যেতে চায় ১২ জন।\n১ জনের মধ্যে যেতে চায় ১২/১০০ জন\n∴ ৫০০ জনের মধ্যে যেতে চায় (১২ × ৫০০)/১০০ = ৬০ জন।\nউত্তর: ৬০ জন।"},{"n":"৩(খ)","q":"একটি বিদ্যালয়ে ৫০০ জন শিক্ষার্থী আছে। প্রধান শিক্ষক সবাইকে নিয়ে পিকনিকে যেতে চান। শিক্ষার্থীরা চিড়িয়াখানা, শিশুপার্ক এবং জাদুঘর এই তিনটির মধ্যে কোনটিতে কতজন যেতে ইচ্ছুক তা নিচের পাই চার্টে দেখানো হলো। [পাই চার্ট PDF-এ ছবি হিসেবে আছে] কতজন শিক্ষার্থী শিশুপার্কে যেতে ইচ্ছুক?","a":"চিত্রে দেওয়া আছে শিশুপার্ক যেতে চায় ৫৫%।\nঅর্থাৎ, ১০০ জনের মধ্যে যেতে চায় ৫৫ জন।\n১ জনের মধ্যে যেতে চায় ৫৫/১০০ জন\n∴ ৫০০ জনের মধ্যে যেতে চায় (৫৫ × ৫০০)/১০০ = ২৭৫ জন।\nউত্তর: ২৭৫ জন।"},{"n":"৩(গ)","q":"একটি বিদ্যালয়ে ৫০০ জন শিক্ষার্থী আছে। প্রধান শিক্ষক সবাইকে নিয়ে পিকনিকে যেতে চান। শিক্ষার্থীরা চিড়িয়াখানা, শিশুপার্ক এবং জাদুঘর এই তিনটির মধ্যে কোনটিতে কতজন যেতে ইচ্ছুক তা নিচের পাই চার্টে দেখানো হলো। [পাই চার্ট PDF-এ ছবি হিসেবে আছে] কতজন শিক্ষার্থী জাদুঘরে যেতে ইচ্ছুক?","a":"চিত্রে দেওয়া আছে শিশুপার্ক যেতে চায় ৩৩%।\nঅর্থাৎ, ১০০ জনের মধ্যে যেতে চায় ৩৩ জন।\n১ জনের মধ্যে যেতে চায় ৩৩/১০০ জন\n∴ ৫০০ জনের মধ্যে যেতে চায় (৩৩ × ৫০০)/১০০ = ১৬৫ জন।\nউত্তর: ১৬৫ জন।"},{"n":"৪(খ)","q":"আমাদের শ্রেণির প্রত্যেক শিক্ষার্থীর ওজন (কেজি) পরিমাপ করি। ৫ শ্রেণি ব্যবধান ধরে একটি সারণি তৈরি করি।","a":"এখানে সর্বনিম্ন ওজন ২৭ কেজি এবং সর্বোচ্চ ওজন ৪৫ কেজি।\nআমরা ২৭ থেকে শুরু করে ৫ করে ব্যবধান নিয়ে শ্রেণিগুলো তৈরি করবো। (যেমন: ২৭-৩১, ৩২-৩৫)।\nশ্রেণি ব্যবধান | ট্যালি চিহ্ন | গণসংখ্যা\n২৭ – ৩১ | 𝍸 |||| | ৯\n৩২ – ৩৬ | 𝍸 𝍸 ||| | ১৩\n৩৭ – ৪১ | 𝍸 𝍸  | ১০\n৪২ – ৪৬ | |||| | ৪\nমোট | | ৩৬"},{"n":"৪(গ)","q":"আমাদের শ্রেণির প্রত্যেক শিক্ষার্থীর ওজন (কেজি) পরিমাপ করি। প্রাপ্ত সারণি থেকে আয়তলেখ আঁকি।","a":"সারণি হতে আয়তলেখ আঁকা হলো: [আয়তলেখটি PDF-এ ছবি হিসেবে আছে, লেখা হিসেবে নেই]"},{"n":"৫(ক)","q":"নিচের রেখাচিত্রে ২০১২ থেকে ২০২০ সালের গড় তাপমাত্রা দেওয়া হলো। [রেখাচিত্র PDF-এ ছবি হিসেবে আছে] ২০১৭ সালের তাপমাত্রা কত ডিগ্রি সেলসিয়াস?","a":"২০১৭ সালের তাপমাত্রা ২০ ও ২৫ ডিগ্রি সেলসিয়াস ঘরের মধ্যে অবস্থান করতেছে।\n২০ ও ২৫ ডিগ্রির মধ্যকার ঘরটির তাপমাত্রা হচ্ছে ২২.৫ ডিগ্রি সেলসিয়াস।\nউত্তর: ২২.৫ ডিগ্রি সেলসিয়াস।"},{"n":"৫(খ)","q":"নিচের রেখাচিত্রে ২০১২ থেকে ২০২০ সালের গড় তাপমাত্রা দেওয়া হলো। [রেখাচিত্র PDF-এ ছবি হিসেবে আছে] কোন সালে সবচেয়ে বেশি তাপমাত্রা ছিল?","a":"রেখাচিত্রের সবচেয়ে উঁচু বিন্দুটি হলো ডানদিকের একেবারে শেষ বিন্দুটি, যা ৩০ এর দাগ বরাবর আছে। এর ঠিক নিচে সালটি হলো ২০২০।\nসুতরাং, ২০২০ সালে সবচেয়ে বেশি তাপমাত্রা ছিল।"},{"n":"৫(গ)","q":"নিচের রেখাচিত্রে ২০১২ থেকে ২০২০ সালের গড় তাপমাত্রা দেওয়া হলো। [রেখাচিত্র PDF-এ ছবি হিসেবে আছে] পাশের রেখাচিত্রের তথ্যের আলোকে একটি সারণি তৈরি করো।","a":"পাশের রেখাচিত্রের তথ্যের আলোকে একটি সারণি তৈরি করা হলো:\nসাল | গড় তাপমাত্রা (ডিগ্রি সেলসিয়াস)\n২০১২ | ২৩\n২০১৩ | ২৫\n২০১৪ | ২৪\n২০১৫ | ২৭\n২০১৬ | ২৬\n২০১৭ | ২৩\n২০১৮ | ২৮\n২০১৯ | ২৭\n২০২০ | ৩০"}]}}]};